"""## 3. Load and verify model-ready datasets

Loads the training, validation, and geographically independent test caches into memory and verifies their tensor dimensions, temporal masks, pixel-validity masks, observation counts, feature channels, target classes, and numerical integrity.
"""

# -------------------------------------------------------
# Required cache contents
# -------------------------------------------------------

REQUIRED_CACHE_KEYS = [
    'X',
    'y',
    'time_mask',
    'valid_pixel_mask',
    'observation_valid_fraction',
    'delta_days',
    'n_observations',
    'patch_ids',
    'dates',
    'bands'
]


def load_and_validate_cache(split, path):
    """
    Load and validate one NPZ dataset split.
    """

    with np.load(path, allow_pickle=False) as npz_file:
        missing_keys = [
            key
            for key in REQUIRED_CACHE_KEYS
            if key not in npz_file.files
        ]

        if missing_keys:
            raise KeyError(
                f'{split} cache is missing keys: {missing_keys}'
            )

        data = {
            key: npz_file[key]
            for key in npz_file.files
        }

    X = data['X']
    y = data['y']
    time_mask = data['time_mask']
    valid_pixel_mask = data['valid_pixel_mask']
    observation_valid_fraction = data[
        'observation_valid_fraction'
    ]
    delta_days = data['delta_days']
    n_observations = data['n_observations']
    patch_ids = data['patch_ids']
    dates = data['dates']
    bands = data['bands']

    N, T, H, W, C = X.shape

    # ---------------------------------------------------
    # Shape checks
    # ---------------------------------------------------

    assert y.shape == (N, H, W)
    assert time_mask.shape == (N, T)
    assert valid_pixel_mask.shape == (N, T, H, W)

    assert observation_valid_fraction.shape == (N, T)
    assert delta_days.shape == (N, T, 1)
    assert n_observations.shape == (N,)

    assert len(patch_ids) == N
    assert len(dates) == T
    assert len(bands) == C

    assert H == PATCH_SIZE
    assert W == PATCH_SIZE
    assert C == N_CHANNELS

    # ---------------------------------------------------
    # Content checks
    # ---------------------------------------------------

    assert np.isfinite(X).all(), (
        f'Non-finite input values found in {split}.'
    )

    assert np.isfinite(delta_days).all(), (
        f'Non-finite delta values found in {split}.'
    )

    expected_observation_counts = (
        time_mask.sum(axis=1).astype(np.int16)
    )

    assert np.array_equal(
        expected_observation_counts,
        n_observations.astype(np.int16)
    ), f'Observation-count mismatch in {split}.'

    assert np.all(
        (observation_valid_fraction >= 0.0) &
        (observation_valid_fraction <= 1.0)
    ), f'Invalid observation fractions in {split}.'

    missing_dates = time_mask == 0

    assert np.all(
        observation_valid_fraction[missing_dates] == 0
    ), f'Missing dates have non-zero quality in {split}.'

    # Recalculate valid fractions from the pixel masks.
    valid_fraction_from_mask = valid_pixel_mask.mean(
        axis=(2, 3)
    )

    available_dates = time_mask == 1

    assert np.allclose(
        valid_fraction_from_mask[available_dates],
        observation_valid_fraction[available_dates],
        atol=1e-6
    ), f'Valid-fraction mismatch in {split}.'

    # Check several absent frames without creating a large copy.
    missing_indices = np.argwhere(missing_dates)

    for patch_index, time_index in missing_indices[:20]:
        assert np.all(
            X[patch_index, time_index] == 0
        ), (
            f'Non-zero missing frame in {split}: '
            f'patch={patch_index}, time={time_index}.'
        )

    # ---------------------------------------------------
    # Label and feature checks
    # ---------------------------------------------------

    target_values = np.unique(y)
    allowed_targets = {0, 1, 2, 3, IGNORE_LABEL}

    assert set(target_values.tolist()).issubset(
        allowed_targets
    ), (
        f'Unexpected target labels in {split}: '
        f'{target_values}'
    )

    assert len(np.unique(patch_ids)) == N, (
        f'Duplicate patch IDs found in {split}.'
    )

    assert list(bands.astype(str)) == FEATURE_NAMES, (
        f'Unexpected feature order in {split}: {bands}'
    )

    memory_gb = sum(
        value.nbytes
        for value in data.values()
        if isinstance(value, np.ndarray)
    ) / 1024**3

    summary = {
        'split': split,
        'patches': N,
        'dates': T,
        'height': H,
        'width': W,
        'channels': C,
        'min_observations': int(n_observations.min()),
        'mean_observations': float(n_observations.mean()),
        'max_observations': int(n_observations.max()),
        'target_values': target_values.tolist(),
        'memory_GB': memory_gb
    }

    return data, summary

cache_data = {}
