"""## 6. Create model-ready PyTorch datasets and data loaders

Creates PyTorch datasets for the training, validation, and geographically independent test splits.

For each sample, the dataset:

- selects the eight non-redundant model channels;
- applies normalization statistics calculated only from training data;
- preserves zero values for missing observations and cloud-masked pixels;
- converts the input to channel-first format `[T, C, H, W]`;
- returns temporal masks, pixel-validity masks, acquisition intervals, observation-quality values, and reference labels.

Spatial augmentation is applied only to training samples. The same rotation or flip is applied consistently across all dates, validity masks, and the reference label map.

Dataset class
"""

# -------------------------------------------------------
# Model-ready PyTorch dataset
# -------------------------------------------------------

class TarnavaModelDataset(Dataset):
    def __init__(
        self,
        split_data,
        feature_indices,
        channel_means,
        channel_stds,
        augment=False
    ):
        self.data = split_data

        self.feature_indices = np.asarray(
            feature_indices,
            dtype=np.int64
        )

        self.channel_means = np.asarray(
            channel_means,
            dtype=np.float32
        )

        self.channel_stds = np.asarray(
            channel_stds,
            dtype=np.float32
        )

        self.augment = augment

        assert self.channel_means.shape == (
            len(self.feature_indices),
        )

        assert self.channel_stds.shape == (
            len(self.feature_indices),
        )

        assert np.all(self.channel_stds > 0)

    def __len__(self):
        return self.data['X'].shape[0]

    @staticmethod
    def apply_spatial_augmentation(
        x,
        y,
        valid_pixel_mask
    ):
        """
        Apply identical spatial transformations to every
        temporal observation, the label map, and validity masks.

        x shape: [T, C, H, W]
        y shape: [H, W]
        valid_pixel_mask shape: [T, H, W]
        """

        # Horizontal flip
        if random.random() < 0.5:
            x = torch.flip(x, dims=[3])
            y = torch.flip(y, dims=[1])

            valid_pixel_mask = torch.flip(
                valid_pixel_mask,
                dims=[2]
            )

        # Vertical flip
        if random.random() < 0.5:
            x = torch.flip(x, dims=[2])
            y = torch.flip(y, dims=[0])

            valid_pixel_mask = torch.flip(
                valid_pixel_mask,
                dims=[1]
            )

        # Rotation by 0, 90, 180, or 270 degrees
        rotation_k = random.randint(0, 3)

        if rotation_k > 0:
            x = torch.rot90(
                x,
                k=rotation_k,
                dims=[2, 3]
            )

            y = torch.rot90(
                y,
                k=rotation_k,
                dims=[0, 1]
            )

            valid_pixel_mask = torch.rot90(
                valid_pixel_mask,
                k=rotation_k,
                dims=[1, 2]
            )

        return x, y, valid_pixel_mask

    def __getitem__(self, index):
        # Select the eight final model channels.
        # Original shape: [T, H, W, 9]
        x = self.data['X'][index][
            ...,
            self.feature_indices
        ].astype(
            np.float32,
            copy=True
        )

        y = self.data['y'][index].astype(
            np.int64,
            copy=True
        )

        time_mask = self.data[
            'time_mask'
        ][index].astype(
            np.float32,
            copy=True
        )

        valid_pixel_mask = self.data[
            'valid_pixel_mask'
        ][index].astype(
            np.bool_,
            copy=True
        )

        observation_valid_fraction = self.data[
            'observation_valid_fraction'
        ][index].astype(
            np.float32,
            copy=True
        )

        delta_days = self.data[
            'delta_days'
        ][index].astype(
            np.float32,
            copy=True
        )

        n_observations = int(
            self.data['n_observations'][index]
        )

        # ---------------------------------------------------
        # Training-only normalization parameters
        # ---------------------------------------------------

        means = self.channel_means.reshape(
            1,
            1,
            1,
            -1
        )

        stds = self.channel_stds.reshape(
            1,
            1,
            1,
            -1
        )

        x = (x - means) / stds

        # Cloud-masked pixels and completely absent frames
        # must remain zero after normalization.
        x[~valid_pixel_mask] = 0.0

        # ---------------------------------------------------
        # Convert to PyTorch tensors
        # ---------------------------------------------------

        x = torch.from_numpy(x).permute(
            0,
            3,
            1,
            2
        ).contiguous()

        y = torch.from_numpy(y)

        time_mask = torch.from_numpy(
            time_mask
        )

        valid_pixel_mask = torch.from_numpy(
            valid_pixel_mask
        )

        observation_valid_fraction = (
            torch.from_numpy(
                observation_valid_fraction
            )
        )

        delta_days = torch.from_numpy(
            delta_days
        )

        if self.augment:
            (
                x,
                y,
                valid_pixel_mask
            ) = self.apply_spatial_augmentation(
                x,
                y,
                valid_pixel_mask
            )

        label_mask = y != IGNORE_LABEL

        return {
            'X': x,
            'y': y,
            'label_mask': label_mask,
            'time_mask': time_mask,
            'valid_pixel_mask': valid_pixel_mask,
            'observation_valid_fraction': (
                observation_valid_fraction
            ),
            'delta_days': delta_days,
            'n_observations': torch.tensor(
                n_observations,
                dtype=torch.long
            ),
            'patch_id': str(
                self.data['patch_ids'][index]
            )
        }

"""Instantiate the datasets"""

