"""## 7. Define segmentation evaluation metrics

Implements a common pixel-level evaluation framework for all models.

Pixels assigned to label 255 are excluded. Metrics are accumulated through a confusion matrix, avoiding the need to retain every prediction in memory.

The reported measures are:

- Overall Accuracy;
- macro and weighted F1-score;
- per-class precision, recall, and F1-score;
- per-class Intersection over Union;
- mean Intersection over Union;
- Cohen's Kappa;
- confusion matrix.

Metric accumulator
"""

# -------------------------------------------------------
# Segmentation metric accumulator
# -------------------------------------------------------

class SegmentationMetricAccumulator:
    def __init__(
        self,
        n_classes,
        class_names,
        ignore_label=255
    ):
        self.n_classes = int(n_classes)
        self.class_names = list(class_names)
        self.ignore_label = int(ignore_label)

        if len(self.class_names) != self.n_classes:
            raise ValueError(
                'class_names length must equal n_classes.'
            )

        self.reset()

    def reset(self):
        self.confusion = np.zeros(
            (
                self.n_classes,
                self.n_classes
            ),
            dtype=np.int64
        )

    def update(
        self,
        predictions,
        targets
    ):
        """
        Update the confusion matrix.

        predictions may be:
        - logits [B, C, H, W];
        - class IDs [B, H, W];
        - class IDs [H, W].

        targets may be:
        - [B, H, W];
        - [H, W].
        """

        if torch.is_tensor(predictions):
            predictions = predictions.detach().cpu()

            if predictions.ndim == 4:
                predictions = predictions.argmax(dim=1)

            predictions = predictions.numpy()

        if torch.is_tensor(targets):
            targets = targets.detach().cpu().numpy()

        predictions = np.asarray(predictions)
        targets = np.asarray(targets)

        if predictions.shape != targets.shape:
            raise ValueError(
                'Prediction and target shapes differ: '
                f'{predictions.shape} vs {targets.shape}'
            )

        predictions = predictions.reshape(-1)
        targets = targets.reshape(-1)

        valid_mask = (
            (targets != self.ignore_label) &
            (targets >= 0) &
            (targets < self.n_classes)
        )

        predictions = predictions[valid_mask]
        targets = targets[valid_mask]

        if predictions.size == 0:
            return

        if np.any(
            (predictions < 0) |
            (predictions >= self.n_classes)
        ):
            unexpected = np.unique(
                predictions[
                    (predictions < 0) |
                    (predictions >= self.n_classes)
                ]
            )

            raise ValueError(
                'Unexpected predicted classes: '
                f'{unexpected.tolist()}'
            )

        encoded = (
            targets.astype(np.int64)
            * self.n_classes
            + predictions.astype(np.int64)
        )

        batch_confusion = np.bincount(
            encoded,
            minlength=(
                self.n_classes
                * self.n_classes
            )
        ).reshape(
            self.n_classes,
            self.n_classes
        )

        self.confusion += batch_confusion

    @staticmethod
    def safe_divide(
        numerator,
        denominator
    ):
        numerator = np.asarray(
            numerator,
            dtype=np.float64
        )

        denominator = np.asarray(
            denominator,
            dtype=np.float64
        )

        output = np.zeros_like(
            numerator,
            dtype=np.float64
        )

        np.divide(
            numerator,
            denominator,
            out=output,
            where=denominator != 0
        )

        return output

    def compute(self):
        confusion = self.confusion.astype(
            np.float64
        )

        total = confusion.sum()

        if total == 0:
            raise RuntimeError(
                'No valid pixels were accumulated.'
            )

        true_positive = np.diag(confusion)

        actual_count = confusion.sum(axis=1)
        predicted_count = confusion.sum(axis=0)

        false_positive = (
            predicted_count - true_positive
        )

        false_negative = (
            actual_count - true_positive
        )

        precision = self.safe_divide(
            true_positive,
            true_positive + false_positive
        )

        recall = self.safe_divide(
            true_positive,
            true_positive + false_negative
        )

        f1 = self.safe_divide(
            2.0 * precision * recall,
            precision + recall
        )

        iou = self.safe_divide(
            true_positive,
            (
                true_positive
                + false_positive
                + false_negative
            )
        )

        overall_accuracy = (
            true_positive.sum() / total
        )

        supported_classes = actual_count > 0

        macro_precision = precision[
            supported_classes
        ].mean()

        macro_recall = recall[
            supported_classes
        ].mean()

        macro_f1 = f1[
            supported_classes
        ].mean()

        mean_iou = iou[
            supported_classes
        ].mean()

        class_frequency = (
            actual_count / total
        )

        weighted_f1 = np.sum(
            f1 * class_frequency
        )

        # Cohen's Kappa
        expected_agreement = np.sum(
            actual_count * predicted_count
        ) / (total ** 2)

        if np.isclose(
            1.0 - expected_agreement,
            0.0
        ):
            kappa = 0.0
        else:
            kappa = (
                overall_accuracy
                - expected_agreement
            ) / (
                1.0
                - expected_agreement
            )

        return {
            'overall_accuracy': float(
                overall_accuracy
            ),
            'macro_precision': float(
                macro_precision
            ),
            'macro_recall': float(
                macro_recall
            ),
            'macro_f1': float(
                macro_f1
            ),
            'weighted_f1': float(
                weighted_f1
            ),
            'mean_iou': float(
                mean_iou
            ),
            'kappa': float(
                kappa
            ),
            'precision_per_class': (
                precision.astype(np.float64)
            ),
            'recall_per_class': (
                recall.astype(np.float64)
            ),
            'f1_per_class': (
                f1.astype(np.float64)
            ),
            'iou_per_class': (
                iou.astype(np.float64)
            ),
            'support_per_class': (
                actual_count.astype(np.int64)
            ),
            'confusion_matrix': (
                self.confusion.copy()
            ),
            'valid_pixel_count': int(total)
        }

"""Convert per-class metrics to a table"""

def per_class_metrics_dataframe(
    metrics,
    class_names
):
    return pd.DataFrame({
        'class_id': np.arange(
            len(class_names)
        ),
        'class_name': class_names,
        'support': metrics[
            'support_per_class'
        ],
        'precision': metrics[
            'precision_per_class'
        ],
        'recall': metrics[
            'recall_per_class'
        ],
        'f1': metrics[
            'f1_per_class'
        ],
        'iou': metrics[
            'iou_per_class'
        ]
    })


def global_metrics_dataframe(
    metrics,
    model_name=None,
    split=None
):
    row = {
        'model': model_name,
        'split': split,
        'overall_accuracy': metrics[
            'overall_accuracy'
        ],
        'macro_precision': metrics[
            'macro_precision'
        ],
        'macro_recall': metrics[
            'macro_recall'
        ],
        'macro_f1': metrics[
            'macro_f1'
        ],
        'weighted_f1': metrics[
            'weighted_f1'
        ],
        'mean_iou': metrics[
            'mean_iou'
        ],
        'kappa': metrics['kappa'],
        'valid_pixel_count': metrics[
            'valid_pixel_count'
        ]
    }

    return pd.DataFrame([row])

"""Confusion-matrix visualization"""

def plot_confusion_matrix(
    confusion,
    class_names,
    normalize=False,
    title='Confusion matrix',
    save_path=None
):
    confusion = np.asarray(
        confusion,
        dtype=np.float64
    )

    if normalize:
        row_totals = confusion.sum(
            axis=1,
            keepdims=True
        )

        confusion_display = np.divide(
            confusion,
            row_totals,
            out=np.zeros_like(confusion),
            where=row_totals != 0
        )

        value_format = '.2f'
    else:
        confusion_display = confusion
        value_format = '.0f'

    fig, ax = plt.subplots(
        figsize=(7, 6)
    )

    image = ax.imshow(
        confusion_display
    )

    ax.set_title(title)
    ax.set_xlabel('Predicted class')
    ax.set_ylabel('Reference class')

    ax.set_xticks(
        np.arange(len(class_names))
    )

    ax.set_yticks(
        np.arange(len(class_names))
    )

    ax.set_xticklabels(
        class_names,
        rotation=45,
        ha='right'
    )

    ax.set_yticklabels(
        class_names
    )

    threshold = (
        confusion_display.max() / 2.0
        if confusion_display.size
        else 0.0
    )

    for row in range(
        confusion_display.shape[0]
    ):
        for column in range(
            confusion_display.shape[1]
        ):
            value = confusion_display[
                row,
                column
            ]

            ax.text(
                column,
                row,
                format(value, value_format),
                ha='center',
                va='center',
                color=(
                    'white'
                    if value > threshold
                    else 'black'
                )
            )

    fig.colorbar(
        image,
        ax=ax,
        fraction=0.046,
        pad=0.04
    )

    fig.tight_layout()

    if save_path is not None:
        fig.savefig(
            save_path,
            dpi=300,
            bbox_inches='tight'
        )

    plt.show()

"""Verify the metric implementation

Use the complete validation labels as perfect predictions
"""

# -------------------------------------------------------
# Perfect-prediction metric test
