"""### 9.6 Verify that pixel locations reconstruct the label maps"""

def reconstruct_rf_label_maps(
    split_name,
    values
):
    split_result = RF_DATA[
        split_name
    ]

    n_patches = len(
        split_result['patch_ids']
    )

    maps = np.full(
        (
            n_patches,
            PATCH_SIZE,
            PATCH_SIZE
        ),
        IGNORE_LABEL,
        dtype=np.int16
    )

    maps[
        split_result['patch_indices'],
        split_result['rows'],
        split_result['columns']
    ] = np.asarray(
        values,
        dtype=np.int16
    )

    return maps


