"""## 10. Train and select the Random Forest baseline

Trains unweighted and class-weighted Random Forest classifiers using the temporal-summary features constructed from the training split.

Both variants use identical hyperparameters. Their validation performance is compared using mean IoU, with macro F1-score used only as a secondary tie-breaker.

The geographically independent test split is not evaluated during model selection.

### 10.1 Configuration
"""

