"""# CNN

## 12. Temporal CNN

Defines a discrete-time convolutional baseline for pixel-level spatio-temporal classification.

Each Sentinel-2 observation is first processed by a shared spatial CNN. The resulting spatial features are then reorganized into one temporal sequence for every pixel location. One-dimensional temporal convolutions model changes across the observation sequence.

A masked temporal mean combines the sequence into a final spatial feature map, which is decoded into four land-cover classes.

The model uses temporal and pixel-validity masks but does not use the actual number of days between acquisitions. It therefore serves as a discrete-time comparison for the subsequent continuous-time CfC and LTC models.

### 12.1 Model configuration
"""

# -------------------------------------------------------
# Temporal CNN configuration
# -------------------------------------------------------

TEMPORAL_CNN_CONFIG = {
    'input_channels': MODEL_N_CHANNELS,
    'spatial_channels': 24,
    'temporal_channels': 32,
    'n_classes': N_CLASSES,
    'dropout': 0.15
}

display(
    pd.DataFrame(
        TEMPORAL_CNN_CONFIG.items(),
        columns=['parameter', 'value']
    )
)

"""### 12.2 Temporal CNN architecture"""

class TemporalCNNSegmentationModel(nn.Module):
    """
    Spatial frame encoder followed by pixel-wise temporal
    convolutions and a segmentation decoder.
    """

    def __init__(
        self,
        input_channels,
        spatial_channels,
        temporal_channels,
        n_classes,
        dropout=0.15
    ):
        super().__init__()

        self.input_channels = int(
            input_channels
        )

        self.spatial_channels = int(
            spatial_channels
        )

        self.temporal_channels = int(
            temporal_channels
        )

        self.n_classes = int(
            n_classes
        )

        # ---------------------------------------------------
        # Shared spatial encoder for every observation
        # ---------------------------------------------------

        self.frame_encoder = nn.Sequential(
            nn.Conv2d(
                self.input_channels,
                self.spatial_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=4,
                num_channels=self.spatial_channels
            ),
            nn.GELU(),

            nn.Conv2d(
                self.spatial_channels,
                self.temporal_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.temporal_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Pixel-wise temporal CNN
        # ---------------------------------------------------
        # One additional channel provides the validity mask.

        self.temporal_encoder = nn.Sequential(
            nn.Conv1d(
                self.temporal_channels + 1,
                self.temporal_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.temporal_channels
            ),
            nn.GELU(),
            nn.Dropout(
                p=dropout
            ),

            nn.Conv1d(
                self.temporal_channels,
                self.temporal_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.temporal_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Pixel-level classification decoder
        # ---------------------------------------------------

        self.decoder = nn.Sequential(
            nn.Conv2d(
                self.temporal_channels,
                self.temporal_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.temporal_channels
            ),
            nn.GELU(),
            nn.Dropout2d(
                p=dropout
            ),
            nn.Conv2d(
                self.temporal_channels,
                self.n_classes,
                kernel_size=1
            )
        )

    def forward(
        self,
        x,
        time_mask,
        delta_days=None,
        valid_pixel_mask=None,
        observation_valid_fraction=None
    ):
        """
        Parameters
        ----------
        x
            Shape [B, T, C, H, W].
        time_mask
            Shape [B, T].
        valid_pixel_mask
            Shape [B, T, H, W].

        Returns
        -------
        logits
            Shape [B, n_classes, H, W].
        """

        if x.ndim != 5:
            raise ValueError(
                'Expected x with shape [B,T,C,H,W].'
            )

        batch_size, time_steps, channels, height, width = (
            x.shape
        )

        if channels != self.input_channels:
            raise ValueError(
                f'Expected {self.input_channels} channels, '
                f'but received {channels}.'
            )

        if valid_pixel_mask is None:
            valid_pixel_mask = torch.ones(
                (
                    batch_size,
                    time_steps,
                    height,
                    width
                ),
                dtype=torch.bool,
                device=x.device
            )

        # A date must be available and the particular pixel
        # must be valid.
        effective_mask = (
            valid_pixel_mask.bool()
            & time_mask.bool()[
                :,
                :,
                None,
                None
            ]
        )

        # Ensure invalid pixels remain zero.
        x = x * effective_mask[
            :,
            :,
            None,
            :,
            :
        ].to(x.dtype)

        # ---------------------------------------------------
        # Spatial encoding
        # ---------------------------------------------------

        frame_input = x.reshape(
            batch_size * time_steps,
            channels,
            height,
            width
        )

        frame_features = self.frame_encoder(
            frame_input
        )

        frame_features = frame_features.reshape(
            batch_size,
            time_steps,
            self.temporal_channels,
            height,
            width
        )

        frame_features = (
            frame_features
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(frame_features.dtype)
        )

        # ---------------------------------------------------
        # Convert every pixel into a temporal sequence
        # ---------------------------------------------------

        temporal_sequences = (
            frame_features
            .permute(
                0,
                3,
                4,
                2,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                self.temporal_channels,
                time_steps
            )
        )

        temporal_mask = (
            effective_mask
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                1,
                time_steps
            )
            .to(
                temporal_sequences.dtype
            )
        )

        temporal_input = torch.cat(
            [
                temporal_sequences,
                temporal_mask
            ],
            dim=1
        )

        temporal_features = (
            self.temporal_encoder(
                temporal_input
            )
        )

        # Ignore unavailable observations during temporal
        # aggregation.
        temporal_features = (
            temporal_features
            * temporal_mask
        )

        valid_counts = temporal_mask.sum(
            dim=-1
        ).clamp_min(1.0)

        aggregated_features = (
            temporal_features.sum(
                dim=-1
            )
            / valid_counts
        )

        aggregated_features = (
            aggregated_features
            .reshape(
                batch_size,
                height,
                width,
                self.temporal_channels
            )
            .permute(
                0,
                3,
                1,
                2
            )
            .contiguous()
        )

        logits = self.decoder(
            aggregated_features
        )

        return logits

"""### 12.3 Instantiate the model"""

temporal_cnn_model = (
    TemporalCNNSegmentationModel(
        **TEMPORAL_CNN_CONFIG
    ).to(DEVICE)
)

