print(TEMPORAL_CNN_CHECKPOINT_PATH)

print('Training-history path:')
print(TEMPORAL_CNN_HISTORY_PATH)

"""### 13.2 Recreate the training loader reproducibly"""

# -------------------------------------------------------
# Reset seeds before actual training
# -------------------------------------------------------

set_reproducible_seed(SEED)

training_loader_generator = torch.Generator()
training_loader_generator.manual_seed(SEED)

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=NUM_WORKERS,
    pin_memory=PIN_MEMORY,
    drop_last=False,
    generator=training_loader_generator
)

print('Training batches:', len(train_loader))

"""### 13.3 Define the reusable fitting function"""

def fit_neural_model(
    model_name,
    model,
    model_config,
    train_data_loader,
    validation_data_loader,
    criterion,
    checkpoint_path,
    history_path,
    maximum_epochs=None
):
    """
    Train a neural segmentation model and retain the checkpoint
    with the highest validation selection metric.
    """

    if maximum_epochs is None:
        maximum_epochs = TRAINING_CONFIG[
            'maximum_epochs'
        ]

    selection_metric = TRAINING_CONFIG[
        'selection_metric'
    ]

    optimizer, scheduler = (
        build_optimizer_and_scheduler(
            model
        )
    )

    scaler = (
        torch.amp.GradScaler('cuda')
        if USE_AMP
        else None
    )

    early_stopping = EarlyStopping(
        patience=TRAINING_CONFIG[
            'early_stopping_patience'
        ],
        min_delta=TRAINING_CONFIG[
            'early_stopping_min_delta'
        ],
        mode='max'
    )

    history_rows = []

    best_epoch = None
    best_validation_value = None

    training_start = time.perf_counter()

    for epoch in range(
        1,
        maximum_epochs + 1
    ):
        epoch_learning_rate = float(
            optimizer.param_groups[0]['lr']
        )

        train_metrics = train_one_epoch(
            model=model,
            data_loader=train_data_loader,
            optimizer=optimizer,
            criterion=criterion,
            device=DEVICE,
            scaler=scaler,
            gradient_clip_norm=(
                TRAINING_CONFIG[
                    'gradient_clip_norm'
                ]
            )
        )

        validation_metrics = evaluate_model(
            model=model,
            data_loader=validation_data_loader,
            criterion=criterion,
            device=DEVICE
        )

        validation_value = float(
            validation_metrics[
                selection_metric
            ]
        )

        improved = early_stopping.step(
            validation_value
        )

        if improved:
            best_epoch = epoch
            best_validation_value = (
                validation_value
            )

            save_model_checkpoint(
                path=checkpoint_path,
                model=model,
                optimizer=optimizer,
                scheduler=scheduler,
                epoch=epoch,
                model_name=model_name,
                validation_metrics=(
                    validation_metrics
                ),
                model_config=model_config
            )

        scheduler.step(
            validation_value
        )

        next_learning_rate = float(
            optimizer.param_groups[0]['lr']
        )

        history_row = {
            'epoch': epoch,
            'learning_rate': (
                epoch_learning_rate
            ),
            'next_learning_rate': (
                next_learning_rate
            ),
            'train_loss': train_metrics[
                'loss'
            ],
            'train_overall_accuracy': (
                train_metrics[
                    'overall_accuracy'
                ]
            ),
            'train_macro_f1': train_metrics[
                'macro_f1'
            ],
            'train_mean_iou': train_metrics[
                'mean_iou'
            ],
            'train_kappa': train_metrics[
                'kappa'
            ],
            'train_seconds': train_metrics[
                'execution_seconds'
            ],
            'validation_loss': (
                validation_metrics[
                    'loss'
                ]
            ),
            'validation_overall_accuracy': (
                validation_metrics[
                    'overall_accuracy'
                ]
            ),
            'validation_macro_f1': (
                validation_metrics[
                    'macro_f1'
                ]
            ),
            'validation_mean_iou': (
                validation_metrics[
                    'mean_iou'
                ]
            ),
            'validation_kappa': (
                validation_metrics[
                    'kappa'
                ]
            ),
            'validation_seconds': (
                validation_metrics[
                    'execution_seconds'
                ]
            ),
            'checkpoint_improved': improved,
            'early_stopping_counter': (
                early_stopping.counter
            )
        }

        history_rows.append(
            history_row
        )

        # Save after every epoch.
        pd.DataFrame(
            history_rows
        ).to_csv(
            history_path,
            index=False
        )

        print(
            f'Epoch {epoch:02d}/{maximum_epochs} | '
            f'lr={epoch_learning_rate:.2e} | '
            f'train loss={train_metrics["loss"]:.4f} | '
            f'train mIoU={train_metrics["mean_iou"]:.4f} | '
            f'valid loss={validation_metrics["loss"]:.4f} | '
            f'valid F1={validation_metrics["macro_f1"]:.4f} | '
            f'valid mIoU={validation_metrics["mean_iou"]:.4f} | '
            f'time={train_metrics["execution_seconds"]:.1f}s'
            f' + {validation_metrics["execution_seconds"]:.1f}s'
            f'{" | saved" if improved else ""}'
        )

        if early_stopping.should_stop:
            print(
                'Early stopping activated at '
                f'epoch {epoch}.'
            )
            break

    total_training_seconds = (
        time.perf_counter()
        - training_start
    )

    if best_epoch is None:
        raise RuntimeError(
            'No valid checkpoint was saved.'
        )

    if not checkpoint_path.exists():
        raise FileNotFoundError(
            f'Missing checkpoint: {checkpoint_path}'
        )

    # This is a checkpoint produced by this notebook.
    checkpoint = torch.load(
        checkpoint_path,
        map_location=DEVICE,
        weights_only=False
    )

    model.load_state_dict(
        checkpoint['model_state_dict']
    )

    history_dataframe = pd.DataFrame(
        history_rows
    )

    result = {
        'model': model,
        'history': history_dataframe,
        'best_epoch': int(best_epoch),
        'best_validation_value': float(
            best_validation_value
        ),
        'total_training_seconds': float(
            total_training_seconds
        ),
        'checkpoint_path': str(
            checkpoint_path
        )
    }

    return result

