"""## 14. Evaluate the Temporal CNN on the independent test region

Loads the best Temporal CNN checkpoint selected exclusively from validation mean IoU and evaluates it once on the geographically independent test region.

The section reports:

- global and per-class test metrics;
- raw and normalized confusion matrices;
- GPU forward-pass and complete evaluation times;
- validation-to-test generalization differences;
- reconstructed 50 × 50 prediction maps.

The test results are not used to modify the architecture, hyperparameters, loss function, or selected checkpoint.

### 14.1 Configure output paths
"""

