"""### 14.3 Evaluation and prediction function"""

@torch.no_grad()
def evaluate_and_collect_predictions(
    model,
    data_loader,
    criterion,
    device
):
    """
    Evaluate a neural segmentation model and retain all
    prediction and reference maps.
    """

    model.eval()

    metric_accumulator = (
        SegmentationMetricAccumulator(
            n_classes=N_CLASSES,
            class_names=CLASS_NAMES,
            ignore_label=IGNORE_LABEL
        )
    )

    prediction_parts = []
    target_parts = []
    patch_ids = []

    total_weighted_loss = 0.0
    total_valid_pixels = 0

    forward_seconds = 0.0
    evaluation_start = time.perf_counter()

    for batch in data_loader:
        batch = move_batch_to_device(
            batch,
            device
        )

        targets = batch['y']

        valid_pixel_count = int(
            (
                targets != IGNORE_LABEL
            ).sum().item()
        )

        amp_context = (
            torch.autocast(
                device_type='cuda',
                dtype=torch.float16
            )
            if USE_AMP
            else nullcontext()
        )

        # Synchronization is required for accurate GPU timing.
        if device.type == 'cuda':
            torch.cuda.synchronize()

        forward_start = time.perf_counter()

        with amp_context:
            logits = forward_model(
                model,
                batch
            )

            loss = criterion(
                logits,
                targets
            )

        if device.type == 'cuda':
            torch.cuda.synchronize()

        forward_seconds += (
            time.perf_counter()
            - forward_start
        )

        if not torch.isfinite(loss):
            raise RuntimeError(
                'Non-finite test loss detected.'
            )

        predictions = logits.argmax(
            dim=1
        )

        metric_accumulator.update(
            predictions=predictions,
            targets=targets
        )

        total_weighted_loss += (
            loss.item()
            * valid_pixel_count
        )

        total_valid_pixels += (
            valid_pixel_count
        )

        prediction_parts.append(
            predictions.detach()
            .cpu()
            .numpy()
            .astype(np.int16)
        )

        target_parts.append(
            targets.detach()
            .cpu()
            .numpy()
            .astype(np.int16)
        )

        patch_ids.extend(
            list(batch['patch_id'])
        )

    evaluation_seconds = (
        time.perf_counter()
        - evaluation_start
    )

    metrics = metric_accumulator.compute()

    metrics['loss'] = (
        total_weighted_loss
        / max(total_valid_pixels, 1)
    )

    predictions = np.concatenate(
        prediction_parts,
        axis=0
    )

    targets = np.concatenate(
        target_parts,
        axis=0
    )

    return {
        'metrics': metrics,
        'predictions': predictions,
        'targets': targets,
        'patch_ids': np.asarray(
            patch_ids,
            dtype=str
        ),
        'forward_seconds': float(
            forward_seconds
        ),
        'evaluation_seconds': float(
            evaluation_seconds
        )
    }

"""### 14.4 Run the independent test evaluation"""

