"""## 16. CNN-LSTM

Defines a recurrent baseline for pixel-level spatio-temporal land-cover classification.

Each Sentinel-2 observation is processed by a shared spatial CNN. For every pixel location, the resulting spatial features form a temporal sequence that is processed by an LSTM.

Cloud-masked pixels and unavailable observations do not update the recurrent hidden state. The final valid hidden state for each pixel is decoded into one of the four land-cover classes.

The model does not use the actual number of days between acquisitions, making it a discrete-time recurrent baseline for comparison with the continuous-time CfC and LTC models.

### 16.1 Model configuration
"""

# -------------------------------------------------------
# CNN-LSTM configuration
# -------------------------------------------------------

CNN_LSTM_NAME = 'cnn_lstm'

CNN_LSTM_CONFIG = {
    'input_channels': MODEL_N_CHANNELS,
    'spatial_channels': 24,
    'feature_channels': 32,
    'hidden_size': 32,
    'n_classes': N_CLASSES,
    'dropout': 0.15
}

display(
    pd.DataFrame(
        CNN_LSTM_CONFIG.items(),
        columns=['parameter', 'value']
    )
)

"""### 16.2 Masked pixel-wise LSTM"""

class MaskedPixelLSTM(nn.Module):
    """
    Applies an LSTM independently to every pixel sequence.

    Invalid observations preserve the previous hidden and cell
    states rather than updating them.
    """

    def __init__(
        self,
        input_size,
        hidden_size,
        dropout=0.15
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.lstm_cell = nn.LSTMCell(
            input_size=self.input_size,
            hidden_size=self.hidden_size
        )

        self.dropout = nn.Dropout(
            p=dropout
        )

    def forward(
        self,
        sequences,
        valid_mask
    ):
        """
        Parameters
        ----------
        sequences
            Shape [N, T, F].
        valid_mask
            Shape [N, T].

        Returns
        -------
        final_hidden
            Shape [N, hidden_size].
        """

        if sequences.ndim != 3:
            raise ValueError(
                'Expected sequences with shape [N,T,F].'
            )

        if valid_mask.shape != sequences.shape[:2]:
            raise ValueError(
                'Temporal sequence and mask shapes differ.'
            )

        n_sequences, time_steps, feature_size = (
            sequences.shape
        )

        if feature_size != self.input_size:
            raise ValueError(
                f'Expected input size {self.input_size}, '
                f'but received {feature_size}.'
            )

        hidden = torch.zeros(
            n_sequences,
            self.hidden_size,
            dtype=sequences.dtype,
            device=sequences.device
        )

        cell = torch.zeros_like(
            hidden
        )

        for time_index in range(time_steps):
            candidate_hidden, candidate_cell = (
                self.lstm_cell(
                    sequences[:, time_index],
                    (hidden, cell)
                )
            )

            step_mask = valid_mask[
                :,
                time_index
            ].unsqueeze(-1).to(
                sequences.dtype
            )

            # Valid observations update the state.
            # Invalid observations preserve the prior state.
            hidden = (
                candidate_hidden * step_mask
                + hidden * (1.0 - step_mask)
            )

            cell = (
                candidate_cell * step_mask
                + cell * (1.0 - step_mask)
            )

        return self.dropout(hidden)

"""### 16.3 CNN–LSTM architecture"""

class CNNLSTMSegmentationModel(nn.Module):
    """
    Shared spatial CNN followed by a masked pixel-wise LSTM
    and a pixel-level segmentation decoder.
    """

    def __init__(
        self,
        input_channels,
        spatial_channels,
        feature_channels,
        hidden_size,
        n_classes,
        dropout=0.15
    ):
        super().__init__()

        self.input_channels = int(
            input_channels
        )

        self.feature_channels = int(
            feature_channels
        )

        self.hidden_size = int(
            hidden_size
        )

        self.n_classes = int(
            n_classes
        )

        # ---------------------------------------------------
        # Shared spatial encoder
        # ---------------------------------------------------

        self.frame_encoder = nn.Sequential(
            nn.Conv2d(
                self.input_channels,
                spatial_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=4,
                num_channels=spatial_channels
            ),
            nn.GELU(),

            nn.Conv2d(
                spatial_channels,
                self.feature_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.feature_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Pixel-wise temporal encoder
        # ---------------------------------------------------

        self.temporal_encoder = MaskedPixelLSTM(
            input_size=self.feature_channels,
            hidden_size=self.hidden_size,
            dropout=dropout
        )

        # ---------------------------------------------------
        # Segmentation decoder
        # ---------------------------------------------------

        self.decoder = nn.Sequential(
            nn.Conv2d(
                self.hidden_size,
                self.hidden_size,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.hidden_size
            ),
            nn.GELU(),
            nn.Dropout2d(
                p=dropout
            ),
            nn.Conv2d(
                self.hidden_size,
                self.n_classes,
                kernel_size=1
            )
        )

    def forward(
        self,
        x,
        time_mask,
        delta_days=None,
        valid_pixel_mask=None,
        observation_valid_fraction=None
    ):
        """
        Parameters
        ----------
        x
            Shape [B, T, C, H, W].
        time_mask
            Shape [B, T].
        valid_pixel_mask
            Shape [B, T, H, W].

        Returns
        -------
        logits
            Shape [B, n_classes, H, W].
        """

        if x.ndim != 5:
            raise ValueError(
                'Expected x with shape [B,T,C,H,W].'
            )

        (
            batch_size,
            time_steps,
            channels,
            height,
            width
        ) = x.shape

        if channels != self.input_channels:
            raise ValueError(
                f'Expected {self.input_channels} channels, '
                f'but received {channels}.'
            )

        if valid_pixel_mask is None:
            valid_pixel_mask = torch.ones(
                (
                    batch_size,
                    time_steps,
                    height,
                    width
                ),
                dtype=torch.bool,
                device=x.device
            )

        effective_mask = (
            valid_pixel_mask.bool()
            & time_mask.bool()[
                :,
                :,
                None,
                None
            ]
        )

        x = (
            x
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(x.dtype)
        )

        # ---------------------------------------------------
        # Spatial encoding
        # ---------------------------------------------------

        frame_input = x.reshape(
            batch_size * time_steps,
            channels,
            height,
            width
        )

        frame_features = self.frame_encoder(
            frame_input
        )

        frame_features = frame_features.reshape(
            batch_size,
            time_steps,
            self.feature_channels,
            height,
            width
        )

        frame_features = (
            frame_features
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(frame_features.dtype)
        )

        # ---------------------------------------------------
        # Create one temporal sequence per pixel
        # ---------------------------------------------------

        pixel_sequences = (
            frame_features
            .permute(
                0,
                3,
                4,
                1,
                2
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps,
                self.feature_channels
            )
        )

        pixel_temporal_mask = (
            effective_mask
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        pixel_features = (
            self.temporal_encoder(
                sequences=pixel_sequences,
                valid_mask=pixel_temporal_mask
            )
        )

        # ---------------------------------------------------
        # Restore spatial structure
        # ---------------------------------------------------

        spatial_features = (
            pixel_features
            .reshape(
                batch_size,
                height,
                width,
                self.hidden_size
            )
            .permute(
                0,
                3,
                1,
                2
            )
            .contiguous()
        )

        logits = self.decoder(
            spatial_features
        )

        return logits

"""### 16.4 Instantiate the CNN–LSTM"""

set_reproducible_seed(SEED)

cnn_lstm_model = (
    CNNLSTMSegmentationModel(
        **CNN_LSTM_CONFIG
    ).to(DEVICE)
)

display(
    parameter_summary_dataframe(
        cnn_lstm_model,
        model_name=CNN_LSTM_NAME
    )
)

print(cnn_lstm_model)

"""### 16.5 Forward-pass consistency check"""

# -------------------------------------------------------
# CNN-LSTM smoke test
# -------------------------------------------------------

cnn_lstm_test_batch = next(
    iter(valid_loader)
)

cnn_lstm_test_batch = (
    move_batch_to_device(
        cnn_lstm_test_batch,
        DEVICE
    )
)

cnn_lstm_model.eval()

if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_start = time.perf_counter()

amp_context = (
    torch.autocast(
        device_type='cuda',
        dtype=torch.float16
    )
    if USE_AMP
    else nullcontext()
)

with torch.no_grad():
    with amp_context:
        cnn_lstm_test_logits = (
            forward_model(
                cnn_lstm_model,
                cnn_lstm_test_batch
            )
        )

        cnn_lstm_test_loss = (
            WEIGHTED_CRITERION(
                cnn_lstm_test_logits,
                cnn_lstm_test_batch['y']
            )
        )

if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_seconds = (
    time.perf_counter()
    - forward_start
)

cnn_lstm_test_probabilities = (
    torch.softmax(
        cnn_lstm_test_logits.float(),
        dim=1
    )
)

print(
    'Input shape:',
    cnn_lstm_test_batch['X'].shape
)

print(
    'Output shape:',
    cnn_lstm_test_logits.shape
)

print(
    'Initial weighted loss:',
    cnn_lstm_test_loss.item()
)

print(
    'Forward time:',
    f'{forward_seconds:.3f} s'
)

print(
    'Output range:',
    float(
        cnn_lstm_test_logits.min()
    ),
    float(
        cnn_lstm_test_logits.max()
    )
)

print(
    'Finite output:',
    torch.isfinite(
        cnn_lstm_test_logits
    ).all().item()
)


assert cnn_lstm_test_logits.shape == (
    BATCH_SIZE,
    N_CLASSES,
    PATCH_SIZE,
    PATCH_SIZE
)

assert torch.isfinite(
    cnn_lstm_test_logits
).all()

assert torch.isfinite(
    cnn_lstm_test_loss
)

assert torch.allclose(
    cnn_lstm_test_probabilities.sum(
        dim=1
    ),
    torch.ones_like(
        cnn_lstm_test_probabilities[
            :,
            0
        ]
    ),
    atol=1e-5
)

print(
    'CNN-LSTM forward-pass checks passed.'
)

"""## 17. Train and validate the CNN–LSTM

Trains the CNN–LSTM using weighted cross-entropy, AdamW optimization, gradient clipping, learning-rate reduction, and early stopping.

The best checkpoint is selected exclusively according to validation mean IoU. Training history is saved after every epoch.

The geographically independent test split is not evaluated during model selection.

### 17.1 Configure output paths
"""

# -------------------------------------------------------
# CNN-LSTM experiment paths
# -------------------------------------------------------

CNN_LSTM_CHECKPOINT_PATH = (
    CHECKPOINT_DIR /
    f'{CNN_LSTM_NAME}_best.pt'
)

