cnn_lstm_loader_generator = torch.Generator()
cnn_lstm_loader_generator.manual_seed(SEED)

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=NUM_WORKERS,
    pin_memory=PIN_MEMORY,
    drop_last=False,
    generator=cnn_lstm_loader_generator
)

print('Training batches:', len(train_loader))

"""### 17.3 Release smoke-test objects and initialize a fresh model"""

# -------------------------------------------------------
# Release Section 16 smoke-test objects
