try:
    del cnn_lstm_test_logits
    del cnn_lstm_test_probabilities
    del cnn_lstm_test_loss
    del cnn_lstm_test_batch
except NameError:
    pass

del cnn_lstm_model

gc.collect()

if DEVICE.type == 'cuda':
    torch.cuda.empty_cache()


# -------------------------------------------------------
# Fresh deterministic CNN-LSTM
# -------------------------------------------------------

