"""## 20. CNN-GRU

Defines a recurrent segmentation baseline using a shared spatial CNN followed by a masked pixel-wise GRU.

Each Sentinel-2 observation is encoded spatially. For every pixel, the resulting feature sequence is processed by a GRU. Invalid observations preserve the previous hidden state and therefore do not influence the temporal representation.

The final valid hidden state is reconstructed as a spatial feature map and decoded into the four land-cover classes.

Like the CNN–LSTM, this model treats observations as discrete ordered steps and does not use the actual acquisition intervals.

### 20.1 Model configuration
"""

# -------------------------------------------------------
# CNN-GRU configuration
# -------------------------------------------------------

CNN_GRU_NAME = 'cnn_gru'

CNN_GRU_CONFIG = {
    'input_channels': MODEL_N_CHANNELS,
    'spatial_channels': 24,
    'feature_channels': 32,
    'hidden_size': 32,
    'n_classes': N_CLASSES,
    'dropout': 0.15
}

display(
    pd.DataFrame(
        CNN_GRU_CONFIG.items(),
        columns=['parameter', 'value']
    )
)

"""### 20.2 Masked pixel-wise GRU"""

class MaskedPixelGRU(nn.Module):
    """
    Applies a GRU independently to every pixel sequence.

    Invalid observations preserve the previous hidden state.
    """

    def __init__(
        self,
        input_size,
        hidden_size,
        dropout=0.15
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.gru_cell = nn.GRUCell(
            input_size=self.input_size,
            hidden_size=self.hidden_size
        )

        self.dropout = nn.Dropout(
            p=dropout
        )

    def forward(
        self,
        sequences,
        valid_mask
    ):
        """
        Parameters
        ----------
        sequences
            Shape [N, T, F].
        valid_mask
            Shape [N, T].

        Returns
        -------
        final_hidden
            Shape [N, hidden_size].
        """

        if sequences.ndim != 3:
            raise ValueError(
                'Expected sequences with shape [N,T,F].'
            )

        if valid_mask.shape != sequences.shape[:2]:
            raise ValueError(
                'Temporal sequence and mask shapes differ.'
            )

        n_sequences, time_steps, feature_size = (
            sequences.shape
        )

        if feature_size != self.input_size:
            raise ValueError(
                f'Expected input size {self.input_size}, '
                f'but received {feature_size}.'
            )

        hidden = torch.zeros(
            n_sequences,
            self.hidden_size,
            dtype=sequences.dtype,
            device=sequences.device
        )

        for time_index in range(time_steps):
            candidate_hidden = self.gru_cell(
                sequences[:, time_index],
                hidden
            )

            step_mask = valid_mask[
                :,
                time_index
            ].unsqueeze(-1).to(
                sequences.dtype
            )

            hidden = (
                candidate_hidden * step_mask
                + hidden * (1.0 - step_mask)
            )

        return self.dropout(hidden)

"""### 20.3 CNN-GRU architecture"""

class CNNGRUSegmentationModel(nn.Module):
    """
    Shared spatial CNN followed by a masked pixel-wise GRU
    and a pixel-level segmentation decoder.
    """

    def __init__(
        self,
        input_channels,
        spatial_channels,
        feature_channels,
        hidden_size,
        n_classes,
        dropout=0.15
    ):
        super().__init__()

        self.input_channels = int(
            input_channels
        )

        self.feature_channels = int(
            feature_channels
        )

        self.hidden_size = int(
            hidden_size
        )

        self.n_classes = int(
            n_classes
        )

        # ---------------------------------------------------
        # Shared spatial encoder
        # ---------------------------------------------------

        self.frame_encoder = nn.Sequential(
            nn.Conv2d(
                self.input_channels,
                spatial_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=4,
                num_channels=spatial_channels
            ),
            nn.GELU(),

            nn.Conv2d(
                spatial_channels,
                self.feature_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.feature_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Pixel-wise temporal encoder
        # ---------------------------------------------------

        self.temporal_encoder = MaskedPixelGRU(
            input_size=self.feature_channels,
            hidden_size=self.hidden_size,
            dropout=dropout
        )

        # ---------------------------------------------------
        # Segmentation decoder
        # ---------------------------------------------------

        self.decoder = nn.Sequential(
            nn.Conv2d(
                self.hidden_size,
                self.hidden_size,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.hidden_size
            ),
            nn.GELU(),
            nn.Dropout2d(
                p=dropout
            ),
            nn.Conv2d(
                self.hidden_size,
                self.n_classes,
                kernel_size=1
            )
        )

    def forward(
        self,
        x,
        time_mask,
        delta_days=None,
        valid_pixel_mask=None,
        observation_valid_fraction=None
    ):
        """
        Parameters
        ----------
        x
            Shape [B, T, C, H, W].
        time_mask
            Shape [B, T].
        valid_pixel_mask
            Shape [B, T, H, W].

        Returns
        -------
        logits
            Shape [B, n_classes, H, W].
        """

        if x.ndim != 5:
            raise ValueError(
                'Expected x with shape [B,T,C,H,W].'
            )

        (
            batch_size,
            time_steps,
            channels,
            height,
            width
        ) = x.shape

        if channels != self.input_channels:
            raise ValueError(
                f'Expected {self.input_channels} channels, '
                f'but received {channels}.'
            )

        if valid_pixel_mask is None:
            valid_pixel_mask = torch.ones(
                (
                    batch_size,
                    time_steps,
                    height,
                    width
                ),
                dtype=torch.bool,
                device=x.device
            )

        effective_mask = (
            valid_pixel_mask.bool()
            & time_mask.bool()[
                :,
                :,
                None,
                None
            ]
        )

        x = (
            x
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(x.dtype)
        )

        # ---------------------------------------------------
        # Spatial encoding
        # ---------------------------------------------------

        frame_input = x.reshape(
            batch_size * time_steps,
            channels,
            height,
            width
        )

        frame_features = self.frame_encoder(
            frame_input
        )

        frame_features = frame_features.reshape(
            batch_size,
            time_steps,
            self.feature_channels,
            height,
            width
        )

        frame_features = (
            frame_features
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(frame_features.dtype)
        )

        # ---------------------------------------------------
        # One temporal feature sequence per pixel
        # ---------------------------------------------------

        pixel_sequences = (
            frame_features
            .permute(
                0,
                3,
                4,
                1,
                2
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps,
                self.feature_channels
            )
        )

        pixel_temporal_mask = (
            effective_mask
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        pixel_features = (
            self.temporal_encoder(
                sequences=pixel_sequences,
                valid_mask=pixel_temporal_mask
            )
        )

        # ---------------------------------------------------
        # Restore the spatial structure
        # ---------------------------------------------------

        spatial_features = (
            pixel_features
            .reshape(
                batch_size,
                height,
                width,
                self.hidden_size
            )
            .permute(
                0,
                3,
                1,
                2
            )
            .contiguous()
        )

        logits = self.decoder(
            spatial_features
        )

        return logits

"""### 20.4 Instantiate the CNN-GRU"""

