"""## 23. Consolidate all completed models

Combines the validation and geographically independent test results for Random Forest, Temporal CNN, CNN–LSTM, and CNN–GRU.

The section produces a test-ranking table and summarizes the validation-to-test generalization decrease of every completed model. Runtime measurements are retained as preliminary values and will be replaced by a controlled repeated benchmark after all architectures have been implemented.

### 23.1 Configure saved-result files
"""

# -------------------------------------------------------
