"""### 23.2 Build the consolidated table"""

COMPARISON_METRICS = [
    'overall_accuracy',
    'macro_precision',
    'macro_recall',
    'macro_f1',
    'weighted_f1',
    'mean_iou',
    'kappa'
]


def load_single_result(path):
    dataframe = pd.read_csv(path)

    if len(dataframe) != 1:
        raise ValueError(
            f'Expected one result row in {path}, '
            f'but found {len(dataframe)}.'
        )

    return dataframe.iloc[0]


def first_numeric_value(row, candidates):
    for column in candidates:
        if (
            column in row.index
            and pd.notna(row[column])
        ):
            return float(row[column])

    return np.nan


def checkpoint_size_mb(path):
    if path is None or not path.exists():
        return np.nan

    return path.stat().st_size / (1024 ** 2)


completed_rows = []

for model_name, model_files in MODEL_RESULT_FILES.items():

    validation_row = load_single_result(
        model_files['validation']
    )

    test_row = load_single_result(
        model_files['test']
    )

    model_storage_mb = checkpoint_size_mb(
        model_files['checkpoint']
    )

    # Random Forest size is stored in its metrics file.
    if model_name == 'Random Forest':
        model_storage_mb = first_numeric_value(
            validation_row,
            ['model_size_mb']
        )

    parameters = first_numeric_value(
        validation_row,
        ['total_parameters', 'parameters']
    )

    training_seconds = first_numeric_value(
        validation_row,
        [
            'total_training_seconds',
            'training_seconds'
        ]
    )

    best_epoch = first_numeric_value(
        validation_row,
        ['best_epoch']
    )

    for split_name, result_row in [
        ('validation', validation_row),
        ('independent_test', test_row)
    ]:
        output_row = {
            'model': model_name,
            'split': split_name
        }

        for metric in COMPARISON_METRICS:
            output_row[metric] = float(
                result_row[metric]
            )

        output_row['parameters'] = parameters
        output_row['model_storage_mb'] = (
            model_storage_mb
        )

        output_row['training_seconds'] = (
            training_seconds
        )

        output_row['best_epoch'] = best_epoch

        if split_name == 'validation':
            output_row[
                'measured_ms_per_patch'
            ] = first_numeric_value(
                result_row,
                [
                    'validation_ms_per_patch',
                    'inference_ms_per_patch'
                ]
            )
        else:
            output_row[
                'measured_ms_per_patch'
            ] = first_numeric_value(
                result_row,
                [
                    'evaluation_ms_per_patch',
                    'end_to_end_ms_per_patch',
                    'inference_ms_per_patch'
                ]
            )

        output_row['runtime_device'] = (
            model_files['device']
        )

        completed_rows.append(output_row)


all_completed_models_df = pd.DataFrame(
    completed_rows
)

