"""## 24.CNN–CfC

Defines the first continuous-time segmentation architecture.

Each Sentinel-2 observation is processed by the same shared spatial CNN used in the discrete recurrent baselines. For every pixel, the resulting feature sequence is processed by a closed-form continuous-time cell.

Unlike the Temporal CNN, CNN–LSTM, and CNN–GRU baselines, the CfC cell explicitly receives the elapsed number of days between observations. When a pixel is invalid because of cloud masking, its hidden state is preserved and the elapsed time is accumulated until the next valid observation.

Elapsed times are expressed in months by dividing the number of days by 30. The resulting pixel-level temporal representation is reconstructed as a 50 × 50 feature map and decoded into the four land-cover classes.

### 24.1 Install and import the official ncps implementation
"""

# -------------------------------------------------------
# Install ncps in the active Colab environment when needed
# -------------------------------------------------------

import importlib.util
import importlib.metadata
import subprocess
import sys


if importlib.util.find_spec('ncps') is None:
    print('Installing ncps...')

    subprocess.check_call([
        sys.executable,
        '-m',
        'pip',
        'install',
        '--quiet',
        'ncps'
    ])


from ncps.torch import CfCCell


try:
    NCPS_VERSION = importlib.metadata.version(
        'ncps'
    )
except importlib.metadata.PackageNotFoundError:
    NCPS_VERSION = 'unknown'


print('ncps version:', NCPS_VERSION)
print('CfCCell imported successfully.')

"""### 24.2 CNN–CfC configuration"""

# -------------------------------------------------------
# CNN-CfC configuration
# -------------------------------------------------------

CNN_CFC_NAME = 'cnn_cfc'

CNN_CFC_CONFIG = {
    'input_channels': MODEL_N_CHANNELS,
    'spatial_channels': 24,
    'feature_channels': 32,
    'hidden_size': 32,
    'n_classes': N_CLASSES,

    'cfc_mode': 'default',
    'backbone_units': 32,
    'backbone_layers': 1,
    'backbone_dropout': 0.0,

    'dropout': 0.15,

    # Express elapsed time in months.
    'time_scale_days': 30.0
}

display(
    pd.DataFrame(
        CNN_CFC_CONFIG.items(),
        columns=['parameter', 'value']
    )
)

"""### 24.3 Masked pixel-wise CfC module"""

class MaskedPixelCfC(nn.Module):
    """
    Applies the official CfC cell independently to every
    pixel sequence.

    Invalid observations preserve the previous hidden state.
    Their elapsed time is accumulated until the next valid
    observation.
    """

    def __init__(
        self,
        input_size,
        hidden_size,
        mode='default',
        backbone_units=32,
        backbone_layers=1,
        backbone_dropout=0.0,
        dropout=0.15,
        time_scale_days=30.0
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.time_scale_days = float(
            time_scale_days
        )

        if self.time_scale_days <= 0:
            raise ValueError(
                'time_scale_days must be positive.'
            )

        self.cfc_cell = CfCCell(
            input_size=self.input_size,
            hidden_size=self.hidden_size,
            mode=mode,
            backbone_units=backbone_units,
            backbone_layers=backbone_layers,
            backbone_dropout=backbone_dropout
        )

        self.dropout = nn.Dropout(
            p=dropout
        )

    def forward(
        self,
        sequences,
        valid_mask,
        delta_days
    ):
        """
        Parameters
        ----------
        sequences
            Tensor [N, T, F].
        valid_mask
            Boolean tensor [N, T].
        delta_days
            Elapsed days between sequence positions [N, T].

        Returns
        -------
        final_hidden
            Tensor [N, hidden_size].
        """

        if sequences.ndim != 3:
            raise ValueError(
                'Expected sequences with shape [N,T,F].'
            )

        if valid_mask.shape != sequences.shape[:2]:
            raise ValueError(
                'Sequence and valid-mask shapes differ.'
            )

        if delta_days.shape != sequences.shape[:2]:
            raise ValueError(
                'Sequence and delta-day shapes differ.'
            )

        (
            n_sequences,
            time_steps,
            feature_size
        ) = sequences.shape

        if feature_size != self.input_size:
            raise ValueError(
                f'Expected {self.input_size} features, '
                f'but received {feature_size}.'
            )

        hidden = torch.zeros(
            n_sequences,
            self.hidden_size,
            dtype=sequences.dtype,
            device=sequences.device
        )

        # Elapsed time since the previous valid update.
        accumulated_time = torch.zeros(
            n_sequences,
            1,
            dtype=sequences.dtype,
            device=sequences.device
        )

        for time_index in range(time_steps):

            step_delta = delta_days[
                :,
                time_index
            ].unsqueeze(-1)

            step_delta = torch.clamp(
                step_delta,
                min=0.0
            )

            # Convert elapsed days to approximately months.
            step_delta = (
                step_delta
                / self.time_scale_days
            )

            accumulated_time = (
                accumulated_time
                + step_delta
            )

            step_mask = valid_mask[
                :,
                time_index
            ].unsqueeze(-1)

            candidate_hidden, _ = (
                self.cfc_cell(
                    sequences[
                        :,
                        time_index
                    ],
                    hidden,
                    accumulated_time
                )
            )

            # Valid observations update the state.
            # Invalid observations preserve it.
            hidden = torch.where(
                step_mask,
                candidate_hidden,
                hidden
            )

            # Reset elapsed time only for pixels that
            # received a valid CfC update.
            accumulated_time = torch.where(
                step_mask,
                torch.zeros_like(
                    accumulated_time
                ),
                accumulated_time
            )

        return self.dropout(hidden)

"""### 24.4 CNN–CfC segmentation architecture"""

class CNNCfCSegmentationModel(nn.Module):
    """
    Shared spatial CNN followed by a masked pixel-wise CfC
    and a pixel-level segmentation decoder.
    """

    def __init__(
        self,
        input_channels,
        spatial_channels,
        feature_channels,
        hidden_size,
        n_classes,
        cfc_mode='default',
        backbone_units=32,
        backbone_layers=1,
        backbone_dropout=0.0,
        dropout=0.15,
        time_scale_days=30.0
    ):
        super().__init__()

        self.input_channels = int(
            input_channels
        )

        self.feature_channels = int(
            feature_channels
        )

        self.hidden_size = int(
            hidden_size
        )

        self.n_classes = int(
            n_classes
        )

        # ---------------------------------------------------
        # Shared spatial encoder
        # ---------------------------------------------------

        self.frame_encoder = nn.Sequential(
            nn.Conv2d(
                self.input_channels,
                spatial_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=4,
                num_channels=spatial_channels
            ),
            nn.GELU(),

            nn.Conv2d(
                spatial_channels,
                self.feature_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.feature_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Continuous-time temporal encoder
        # ---------------------------------------------------

        self.temporal_encoder = MaskedPixelCfC(
            input_size=self.feature_channels,
            hidden_size=self.hidden_size,
            mode=cfc_mode,
            backbone_units=backbone_units,
            backbone_layers=backbone_layers,
            backbone_dropout=backbone_dropout,
            dropout=dropout,
            time_scale_days=time_scale_days
        )

        # ---------------------------------------------------
        # Segmentation decoder
        # ---------------------------------------------------

        self.decoder = nn.Sequential(
            nn.Conv2d(
                self.hidden_size,
                self.hidden_size,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.hidden_size
            ),
            nn.GELU(),
            nn.Dropout2d(
                p=dropout
            ),
            nn.Conv2d(
                self.hidden_size,
                self.n_classes,
                kernel_size=1
            )
        )

    def forward(
        self,
        x,
        time_mask,
        delta_days,
        valid_pixel_mask=None,
        observation_valid_fraction=None
    ):
        """
        Parameters
        ----------
        x
            Shape [B, T, C, H, W].
        time_mask
            Shape [B, T].
        delta_days
            Shape [B, T, 1] or [B, T].
        valid_pixel_mask
            Shape [B, T, H, W].

        Returns
        -------
        logits
            Shape [B, n_classes, H, W].
        """

        if x.ndim != 5:
            raise ValueError(
                'Expected x with shape [B,T,C,H,W].'
            )

        (
            batch_size,
            time_steps,
            channels,
            height,
            width
        ) = x.shape

        if channels != self.input_channels:
            raise ValueError(
                f'Expected {self.input_channels} channels, '
                f'but received {channels}.'
            )

        if delta_days is None:
            raise ValueError(
                'CNN-CfC requires delta_days.'
            )

        if (
            delta_days.ndim == 3
            and delta_days.shape[-1] == 1
        ):
            delta_days = delta_days[
                :,
                :,
                0
            ]

        if delta_days.shape != (
            batch_size,
            time_steps
        ):
            raise ValueError(
                'Expected delta_days with shape '
                f'[{batch_size},{time_steps}] or '
                f'[{batch_size},{time_steps},1], but '
                f'received {tuple(delta_days.shape)}.'
            )

        if valid_pixel_mask is None:
            valid_pixel_mask = torch.ones(
                (
                    batch_size,
                    time_steps,
                    height,
                    width
                ),
                dtype=torch.bool,
                device=x.device
            )

        effective_mask = (
            valid_pixel_mask.bool()
            & time_mask.bool()[
                :,
                :,
                None,
                None
            ]
        )

        x = (
            x
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(x.dtype)
        )

        # ---------------------------------------------------
        # Spatial encoding
        # ---------------------------------------------------

        frame_input = x.reshape(
            batch_size * time_steps,
            channels,
            height,
            width
        )

        frame_features = self.frame_encoder(
            frame_input
        )

        frame_features = frame_features.reshape(
            batch_size,
            time_steps,
            self.feature_channels,
            height,
            width
        )

        frame_features = (
            frame_features
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(frame_features.dtype)
        )

        # ---------------------------------------------------
        # One temporal sequence per pixel
        # ---------------------------------------------------

        pixel_sequences = (
            frame_features
            .permute(
                0,
                3,
                4,
                1,
                2
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps,
                self.feature_channels
            )
        )

        pixel_temporal_mask = (
            effective_mask
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        # The acquisition intervals are shared across all
        # pixels in a patch and then flattened consistently.
        pixel_delta_days = (
            delta_days[
                :,
                :,
                None,
                None
            ]
            .expand(
                batch_size,
                time_steps,
                height,
                width
            )
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        pixel_features = (
            self.temporal_encoder(
                sequences=pixel_sequences,
                valid_mask=pixel_temporal_mask,
                delta_days=pixel_delta_days
            )
        )

        # ---------------------------------------------------
        # Restore spatial structure
        # ---------------------------------------------------

        spatial_features = (
            pixel_features
            .reshape(
                batch_size,
                height,
                width,
                self.hidden_size
            )
            .permute(
                0,
                3,
                1,
                2
            )
            .contiguous()
        )

        logits = self.decoder(
            spatial_features
        )

        return logits

"""### 24.5 Instantiate the CNN–CfC"""

set_reproducible_seed(SEED)

cnn_cfc_model = (
    CNNCfCSegmentationModel(
        **CNN_CFC_CONFIG
    ).to(DEVICE)
)

cnn_cfc_parameter_summary = (
    parameter_summary_dataframe(
        cnn_cfc_model,
        model_name=CNN_CFC_NAME
    )
)

display(cnn_cfc_parameter_summary)

print(cnn_cfc_model)

"""### 24.6 Forward-pass and elapsed-time sensitivity checks"""

# -------------------------------------------------------
# CNN-CfC smoke test
# -------------------------------------------------------

cnn_cfc_test_batch = next(
    iter(valid_loader)
)

cnn_cfc_test_batch = (
    move_batch_to_device(
        cnn_cfc_test_batch,
        DEVICE
    )
)

cnn_cfc_model.eval()

if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_start = time.perf_counter()

amp_context = (
    torch.autocast(
        device_type='cuda',
        dtype=torch.float16
    )
    if USE_AMP
    else nullcontext()
)

with torch.no_grad():
    with amp_context:
        cnn_cfc_test_logits = (
            forward_model(
                cnn_cfc_model,
                cnn_cfc_test_batch
            )
        )

        cnn_cfc_test_loss = (
            WEIGHTED_CRITERION(
                cnn_cfc_test_logits,
                cnn_cfc_test_batch['y']
            )
        )

if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_seconds = (
    time.perf_counter()
    - forward_start
)


# -------------------------------------------------------
# Verify that changing delta_days changes the output
# -------------------------------------------------------

modified_time_batch = dict(
    cnn_cfc_test_batch
)

modified_time_batch['delta_days'] = (
    cnn_cfc_test_batch[
        'delta_days'
    ].clone()
)

positive_gap_mask = (
    modified_time_batch[
        'delta_days'
    ] > 0
)

modified_time_batch[
    'delta_days'
][positive_gap_mask] *= 2.0


with torch.no_grad():
    with amp_context:
        modified_time_logits = (
            forward_model(
                cnn_cfc_model,
                modified_time_batch
            )
        )


time_sensitivity = float(
    torch.mean(
        torch.abs(
            cnn_cfc_test_logits.float()
            - modified_time_logits.float()
        )
    ).item()
)


cnn_cfc_test_probabilities = (
    torch.softmax(
        cnn_cfc_test_logits.float(),
        dim=1
    )
)


print(
    'Input shape:',
    cnn_cfc_test_batch['X'].shape
)

print(
    'Delta-days shape:',
    cnn_cfc_test_batch[
        'delta_days'
    ].shape
)

print(
    'Output shape:',
    cnn_cfc_test_logits.shape
)

print(
    'Initial weighted loss:',
    cnn_cfc_test_loss.item()
)

print(
    'Forward time:',
    f'{forward_seconds:.3f} s'
)

print(
    'Output range:',
    float(
        cnn_cfc_test_logits.min()
    ),
    float(
        cnn_cfc_test_logits.max()
    )
)

print(
    'Mean output change after doubling gaps:',
    time_sensitivity
)

print(
    'Finite output:',
    torch.isfinite(
        cnn_cfc_test_logits
    ).all().item()
)


assert cnn_cfc_test_logits.shape == (
    BATCH_SIZE,
    N_CLASSES,
    PATCH_SIZE,
    PATCH_SIZE
)

assert torch.isfinite(
    cnn_cfc_test_logits
).all()

assert torch.isfinite(
    cnn_cfc_test_loss
)

assert torch.allclose(
    cnn_cfc_test_probabilities.sum(
        dim=1
    ),
    torch.ones_like(
        cnn_cfc_test_probabilities[
            :,
            0
        ]
    ),
    atol=1e-5
)

assert count_model_parameters(
    cnn_cfc_model
)['trainable_parameters'] == 24468

assert time_sensitivity > 0.0, (
    'CNN-CfC output did not respond to delta_days.'
)

print(
    'CNN-CfC forward-pass and '
    'elapsed-time checks passed.'
)

