"""## 28. CNN–LTC

Defines a Liquid Time-Constant segmentation architecture using the official `ncps` implementation.

Each Sentinel-2 observation is encoded by the shared spatial CNN. The resulting feature sequence for every pixel is processed by an LTC cell whose hidden-state dynamics depend explicitly on the elapsed time between valid observations.

Cloud-invalid observations preserve the previous liquid state, while their elapsed intervals are accumulated until the next valid observation. Elapsed time is expressed in months by dividing days by 30.

A minimum elapsed time of one day is used for the first valid observation because the LTC numerical solver requires a positive integration interval.

### 28.1 Import the official LTC components
"""

# -------------------------------------------------------
# Official ncps LTC implementation
# -------------------------------------------------------

from ncps.torch import LTCCell
from ncps.wirings import FullyConnected

print('ncps version:', NCPS_VERSION)
print('LTCCell and FullyConnected imported successfully.')

"""### 28.2 CNN–LTC configuration"""

# -------------------------------------------------------
# CNN-LTC configuration
# -------------------------------------------------------

CNN_LTC_NAME = 'cnn_ltc'

CNN_LTC_CONFIG = {
    'input_channels': MODEL_N_CHANNELS,
    'spatial_channels': 24,
    'feature_channels': 32,
    'hidden_size': 32,
    'n_classes': N_CLASSES,

    'input_mapping': 'affine',
    'output_mapping': 'affine',

    # Number of numerical ODE subdivisions per update.
    'ode_unfolds': 6,

    # Uses differentiable positive parameter constraints.
    'implicit_param_constraints': True,

    'wiring_seed': 1111,
    'dropout': 0.15,

    # Convert days into approximately months.
    'time_scale_days': 30.0,

    # Prevent a zero integration interval on the first date.
    'minimum_elapsed_days': 1.0
}

display(
    pd.DataFrame(
        CNN_LTC_CONFIG.items(),
        columns=['parameter', 'value']
    )
)

"""### 28.3 Masked pixel-wise LTC module"""

class MaskedPixelLTC(nn.Module):
    """
    Applies an official fully connected LTC cell independently
    to every pixel sequence.

    Invalid observations preserve the previous state. Their
    elapsed time is accumulated until the next valid update.
    """

    def __init__(
        self,
        input_size,
        hidden_size,
        input_mapping='affine',
        output_mapping='affine',
        ode_unfolds=6,
        implicit_param_constraints=True,
        wiring_seed=1111,
        dropout=0.15,
        time_scale_days=30.0,
        minimum_elapsed_days=1.0
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.time_scale_days = float(
            time_scale_days
        )

        self.minimum_elapsed_days = float(
            minimum_elapsed_days
        )

        if self.time_scale_days <= 0:
            raise ValueError(
                'time_scale_days must be positive.'
            )

        if self.minimum_elapsed_days <= 0:
            raise ValueError(
                'minimum_elapsed_days must be positive.'
            )

        # A dense wiring provides the same 32-unit temporal
        # state width used by the LSTM, GRU, and CfC models.
        self.wiring = FullyConnected(
            units=self.hidden_size,
            output_dim=self.hidden_size,
            erev_init_seed=int(wiring_seed),
            self_connections=True
        )

        self.ltc_cell = LTCCell(
            wiring=self.wiring,
            in_features=self.input_size,
            input_mapping=input_mapping,
            output_mapping=output_mapping,
            ode_unfolds=int(ode_unfolds),
            epsilon=1e-8,
            implicit_param_constraints=(
                implicit_param_constraints
            )
        )

        self.dropout = nn.Dropout(
            p=dropout
        )

    def forward(
        self,
        sequences,
        valid_mask,
        delta_days
    ):
        """
        Parameters
        ----------
        sequences
            Tensor [N, T, F].
        valid_mask
            Boolean tensor [N, T].
        delta_days
            Elapsed days between sequence positions [N, T].

        Returns
        -------
        final_hidden
            Tensor [N, hidden_size].
        """

        if sequences.ndim != 3:
            raise ValueError(
                'Expected sequences with shape [N,T,F].'
            )

        if valid_mask.shape != sequences.shape[:2]:
            raise ValueError(
                'Sequence and valid-mask shapes differ.'
            )

        if delta_days.shape != sequences.shape[:2]:
            raise ValueError(
                'Sequence and delta-day shapes differ.'
            )

        (
            n_sequences,
            time_steps,
            feature_size
        ) = sequences.shape

        if feature_size != self.input_size:
            raise ValueError(
                f'Expected {self.input_size} features, '
                f'but received {feature_size}.'
            )

        # LTC numerical dynamics are kept in float32 for
        # stability even when the surrounding model uses AMP.
        ltc_context = (
            torch.autocast(
                device_type='cuda',
                enabled=False
            )
            if sequences.is_cuda
            else nullcontext()
        )

        with ltc_context:
            sequences_float = sequences.float()
            delta_days_float = delta_days.float()

            hidden = torch.zeros(
                n_sequences,
                self.hidden_size,
                dtype=torch.float32,
                device=sequences.device
            )

            accumulated_time = torch.zeros(
                n_sequences,
                1,
                dtype=torch.float32,
                device=sequences.device
            )

            minimum_elapsed_time = (
                self.minimum_elapsed_days
                / self.time_scale_days
            )

            for time_index in range(time_steps):

                step_delta = delta_days_float[
                    :,
                    time_index
                ].unsqueeze(-1)

                step_delta = torch.clamp(
                    step_delta,
                    min=0.0
                )

                step_delta = (
                    step_delta
                    / self.time_scale_days
                )

                accumulated_time = (
                    accumulated_time
                    + step_delta
                )

                # LTCCell divides by elapsed time internally,
                # so every evaluated interval must be positive.
                elapsed_time = torch.clamp(
                    accumulated_time,
                    min=minimum_elapsed_time
                )

                _, candidate_hidden = (
                    self.ltc_cell(
                        sequences_float[
                            :,
                            time_index
                        ],
                        hidden,
                        elapsed_time=elapsed_time
                    )
                )

                step_mask = valid_mask[
                    :,
                    time_index
                ].unsqueeze(-1).bool()

                hidden = torch.where(
                    step_mask,
                    candidate_hidden,
                    hidden
                )

                accumulated_time = torch.where(
                    step_mask,
                    torch.zeros_like(
                        accumulated_time
                    ),
                    accumulated_time
                )

            hidden = self.dropout(hidden)

        return hidden

"""### 28.4 CNN–LTC segmentation architecture"""

class CNNLTCSegmentationModel(nn.Module):
    """
    Shared spatial CNN followed by a masked pixel-wise LTC
    and a pixel-level segmentation decoder.
    """

    def __init__(
        self,
        input_channels,
        spatial_channels,
        feature_channels,
        hidden_size,
        n_classes,
        input_mapping='affine',
        output_mapping='affine',
        ode_unfolds=6,
        implicit_param_constraints=True,
        wiring_seed=1111,
        dropout=0.15,
        time_scale_days=30.0,
        minimum_elapsed_days=1.0
    ):
        super().__init__()

        self.input_channels = int(
            input_channels
        )

        self.feature_channels = int(
            feature_channels
        )

        self.hidden_size = int(
            hidden_size
        )

        self.n_classes = int(
            n_classes
        )

        # ---------------------------------------------------
        # Shared spatial encoder
        # ---------------------------------------------------

        self.frame_encoder = nn.Sequential(
            nn.Conv2d(
                self.input_channels,
                spatial_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=4,
                num_channels=spatial_channels
            ),
            nn.GELU(),

            nn.Conv2d(
                spatial_channels,
                self.feature_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.feature_channels
            ),
            nn.GELU()
        )

        # ---------------------------------------------------
        # Liquid time-constant temporal encoder
        # ---------------------------------------------------

        self.temporal_encoder = MaskedPixelLTC(
            input_size=self.feature_channels,
            hidden_size=self.hidden_size,
            input_mapping=input_mapping,
            output_mapping=output_mapping,
            ode_unfolds=ode_unfolds,
            implicit_param_constraints=(
                implicit_param_constraints
            ),
            wiring_seed=wiring_seed,
            dropout=dropout,
            time_scale_days=time_scale_days,
            minimum_elapsed_days=(
                minimum_elapsed_days
            )
        )

        # ---------------------------------------------------
        # Segmentation decoder
        # ---------------------------------------------------

        self.decoder = nn.Sequential(
            nn.Conv2d(
                self.hidden_size,
                self.hidden_size,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.GroupNorm(
                num_groups=8,
                num_channels=self.hidden_size
            ),
            nn.GELU(),
            nn.Dropout2d(
                p=dropout
            ),
            nn.Conv2d(
                self.hidden_size,
                self.n_classes,
                kernel_size=1
            )
        )

    def forward(
        self,
        x,
        time_mask,
        delta_days,
        valid_pixel_mask=None,
        observation_valid_fraction=None
    ):
        """
        Parameters
        ----------
        x
            Shape [B, T, C, H, W].
        time_mask
            Shape [B, T].
        delta_days
            Shape [B, T, 1] or [B, T].
        valid_pixel_mask
            Shape [B, T, H, W].

        Returns
        -------
        logits
            Shape [B, n_classes, H, W].
        """

        if x.ndim != 5:
            raise ValueError(
                'Expected x with shape [B,T,C,H,W].'
            )

        (
            batch_size,
            time_steps,
            channels,
            height,
            width
        ) = x.shape

        if channels != self.input_channels:
            raise ValueError(
                f'Expected {self.input_channels} channels, '
                f'but received {channels}.'
            )

        if delta_days is None:
            raise ValueError(
                'CNN-LTC requires delta_days.'
            )

        if (
            delta_days.ndim == 3
            and delta_days.shape[-1] == 1
        ):
            delta_days = delta_days[
                :,
                :,
                0
            ]

        if delta_days.shape != (
            batch_size,
            time_steps
        ):
            raise ValueError(
                'Expected delta_days with shape '
                f'[{batch_size},{time_steps}] or '
                f'[{batch_size},{time_steps},1], but '
                f'received {tuple(delta_days.shape)}.'
            )

        if valid_pixel_mask is None:
            valid_pixel_mask = torch.ones(
                (
                    batch_size,
                    time_steps,
                    height,
                    width
                ),
                dtype=torch.bool,
                device=x.device
            )

        effective_mask = (
            valid_pixel_mask.bool()
            & time_mask.bool()[
                :,
                :,
                None,
                None
            ]
        )

        x = (
            x
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(x.dtype)
        )

        # ---------------------------------------------------
        # Spatial encoding
        # ---------------------------------------------------

        frame_input = x.reshape(
            batch_size * time_steps,
            channels,
            height,
            width
        )

        frame_features = self.frame_encoder(
            frame_input
        )

        frame_features = frame_features.reshape(
            batch_size,
            time_steps,
            self.feature_channels,
            height,
            width
        )

        frame_features = (
            frame_features
            * effective_mask[
                :,
                :,
                None,
                :,
                :
            ].to(frame_features.dtype)
        )

        # ---------------------------------------------------
        # One temporal sequence per pixel
        # ---------------------------------------------------

        pixel_sequences = (
            frame_features
            .permute(
                0,
                3,
                4,
                1,
                2
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps,
                self.feature_channels
            )
        )

        pixel_temporal_mask = (
            effective_mask
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        pixel_delta_days = (
            delta_days[
                :,
                :,
                None,
                None
            ]
            .expand(
                batch_size,
                time_steps,
                height,
                width
            )
            .permute(
                0,
                2,
                3,
                1
            )
            .reshape(
                batch_size
                * height
                * width,
                time_steps
            )
        )

        pixel_features = (
            self.temporal_encoder(
                sequences=pixel_sequences,
                valid_mask=pixel_temporal_mask,
                delta_days=pixel_delta_days
            )
        )

        # ---------------------------------------------------
        # Restore spatial structure
        # ---------------------------------------------------

        spatial_features = (
            pixel_features
            .reshape(
                batch_size,
                height,
                width,
                self.hidden_size
            )
            .permute(
                0,
                3,
                1,
                2
            )
            .contiguous()
        )

        logits = self.decoder(
            spatial_features
        )

        return logits

"""### 28.5 Instantiate the CNN–LTC"""

set_reproducible_seed(SEED)

cnn_ltc_model = (
    CNNLTCSegmentationModel(
        **CNN_LTC_CONFIG
    ).to(DEVICE)
)

cnn_ltc_parameter_summary = (
    parameter_summary_dataframe(
        cnn_ltc_model,
        model_name=CNN_LTC_NAME
    )
)

display(cnn_ltc_parameter_summary)

print(cnn_ltc_model)

"""### 28.6 Forward-pass and elapsed-time sensitivity checks"""

# -------------------------------------------------------
# CNN-LTC smoke test
# -------------------------------------------------------

cnn_ltc_test_batch = next(
    iter(valid_loader)
)

cnn_ltc_test_batch = (
    move_batch_to_device(
        cnn_ltc_test_batch,
        DEVICE
    )
)

cnn_ltc_model.eval()


def cnn_ltc_amp_context():
    return (
        torch.autocast(
            device_type='cuda',
            dtype=torch.float16
        )
        if USE_AMP
        else nullcontext()
    )


if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_start = time.perf_counter()

with torch.no_grad():
    with cnn_ltc_amp_context():
        cnn_ltc_test_logits = (
            forward_model(
                cnn_ltc_model,
                cnn_ltc_test_batch
            )
        )

        cnn_ltc_test_loss = (
            WEIGHTED_CRITERION(
                cnn_ltc_test_logits,
                cnn_ltc_test_batch['y']
            )
        )

if DEVICE.type == 'cuda':
    torch.cuda.synchronize()

forward_seconds = (
    time.perf_counter()
    - forward_start
)


# -------------------------------------------------------
# Verify dependence on elapsed time
# -------------------------------------------------------

modified_ltc_time_batch = dict(
    cnn_ltc_test_batch
)

modified_ltc_time_batch[
    'delta_days'
] = cnn_ltc_test_batch[
    'delta_days'
].clone()

positive_gap_mask = (
    modified_ltc_time_batch[
        'delta_days'
    ] > 0
)

modified_ltc_time_batch[
    'delta_days'
][positive_gap_mask] *= 2.0


with torch.no_grad():
    with cnn_ltc_amp_context():
        modified_ltc_time_logits = (
            forward_model(
                cnn_ltc_model,
                modified_ltc_time_batch
            )
        )


ltc_time_sensitivity = float(
    torch.mean(
        torch.abs(
            cnn_ltc_test_logits.float()
            - modified_ltc_time_logits.float()
        )
    ).item()
)


cnn_ltc_test_probabilities = (
    torch.softmax(
        cnn_ltc_test_logits.float(),
        dim=1
    )
)


print(
    'Input shape:',
    cnn_ltc_test_batch['X'].shape
)

print(
    'Delta-days shape:',
    cnn_ltc_test_batch[
        'delta_days'
    ].shape
)

print(
    'Output shape:',
    cnn_ltc_test_logits.shape
)

print(
    'Initial weighted loss:',
    cnn_ltc_test_loss.item()
)

print(
    'Forward time:',
    f'{forward_seconds:.3f} s'
)

print(
    'Output range:',
    float(cnn_ltc_test_logits.min()),
    float(cnn_ltc_test_logits.max())
)

print(
    'Mean output change after doubling gaps:',
    ltc_time_sensitivity
)

print(
    'Finite output:',
    torch.isfinite(
        cnn_ltc_test_logits
    ).all().item()
)

print(
    'LTC internal synapses:',
    int(
        cnn_ltc_model
        .temporal_encoder
        .ltc_cell
        .synapse_count
    )
)


assert cnn_ltc_test_logits.shape == (
    BATCH_SIZE,
    N_CLASSES,
    PATCH_SIZE,
    PATCH_SIZE
)

assert torch.isfinite(
    cnn_ltc_test_logits
).all()

assert torch.isfinite(
    cnn_ltc_test_loss
)

assert torch.allclose(
    cnn_ltc_test_probabilities.sum(
        dim=1
    ),
    torch.ones_like(
        cnn_ltc_test_probabilities[
            :,
            0
        ]
    ),
    atol=1e-5
)

assert count_model_parameters(
    cnn_ltc_model
)['trainable_parameters'] == 26580

assert ltc_time_sensitivity > 0.0, (
    'CNN-LTC output did not respond to delta_days.'
)

print(
    'CNN-LTC forward-pass and '
    'elapsed-time checks passed.'
)

