"""# Experiment 2

## 32. Analyze temporal irregularity

Quantifies the irregular temporal structure of the Sentinel-2 sequences.

Two forms of irregularity are analyzed. Acquisition-level gaps describe the number of days between successive observations available for each patch. Pixel-level effective gaps additionally account for cloud masking and therefore measure the actual elapsed time between successive valid observations of each spatial location.

The analysis is performed independently for the training, validation, and test splits. These statistics are used to configure the subsequent continuous-time experiments but do not modify the existing six-model baseline results.

### 32.1 Temporal-gap extraction utilities
"""

# -------------------------------------------------------
# Temporal-irregularity utilities
# -------------------------------------------------------

def histogram_quantile(histogram, quantile):
    """
    Exact quantile from an integer-valued histogram.
    """

    histogram = np.asarray(
        histogram,
        dtype=np.int64
    )

    total = histogram.sum()

    if total == 0:
        return np.nan

    target = quantile * (total - 1)

    cumulative = np.cumsum(histogram)

    return int(
        np.searchsorted(
            cumulative,
            target + 1,
            side='left'
        )
    )


def histogram_mean(histogram):
    """
    Exact arithmetic mean from an integer-valued histogram.
    """

    histogram = np.asarray(
        histogram,
        dtype=np.int64
    )

    total = histogram.sum()

    if total == 0:
        return np.nan

    values = np.arange(
        len(histogram)
    )

    return float(
        np.sum(
            values * histogram
        )
        / total
    )

"""### 32.2 Analyze one split"""

def analyze_temporal_irregularity(
    split_name,
    split_data
):
    """
    Analyze patch-level acquisition gaps and effective
    pixel-level temporal gaps.
    """

    time_mask = (
        split_data[
            'time_mask'
        ].astype(bool)
    )

    valid_pixel_mask = (
        split_data[
            'valid_pixel_mask'
        ].astype(bool)
    )

    delta_days = (
        split_data[
            'delta_days'
        ][..., 0]
    )

    dates = pd.to_datetime(
        split_data['dates']
    )

    n_patches, n_dates = (
        time_mask.shape
    )

    _, _, height, width = (
        valid_pixel_mask.shape
    )


    # ---------------------------------------------------
    # Date range
    # ---------------------------------------------------

    first_date = dates.min()
    last_date = dates.max()

    date_span_days = int(
        (
            last_date
            - first_date
        ).days
    )

    day_offsets = np.asarray(
        (
            dates
            - first_date
        ).days,
        dtype=np.int32
    )


    # ---------------------------------------------------
    # Observation counts per patch
    # ---------------------------------------------------

    observations_per_patch = (
        time_mask.sum(axis=1)
    )

    missing_fraction_per_patch = (
        1.0
        - observations_per_patch
        / n_dates
    )


    # ---------------------------------------------------
    # Acquisition-level gaps
    # ---------------------------------------------------

    acquisition_gap_mask = (
        time_mask
        & (delta_days > 0)
    )

    acquisition_gaps = (
        delta_days[
            acquisition_gap_mask
        ].astype(np.int32)
    )


    # ---------------------------------------------------
    # Effective pixel-level gaps
    #
    # For every pixel, store the calendar day of its
    # previous valid observation.
    # ---------------------------------------------------

    max_possible_gap = (
        date_span_days + 1
    )

    pixel_gap_histogram = np.zeros(
        max_possible_gap + 1,
        dtype=np.int64
    )

    last_valid_day = np.full(
        (
            n_patches,
            height,
            width
        ),
        -1,
        dtype=np.int32
    )


    for time_index in range(n_dates):

        current_day = int(
            day_offsets[time_index]
        )

        current_valid = (
            valid_pixel_mask[
                :,
                time_index
            ]
            &
            time_mask[
                :,
                time_index,
                None,
                None
            ]
        )

        has_previous = (
            last_valid_day >= 0
        )

        gap_mask = (
            current_valid
            & has_previous
        )

        if np.any(gap_mask):

            current_gaps = (
                current_day
                - last_valid_day[
                    gap_mask
                ]
            )

            current_counts = np.bincount(
                current_gaps,
                minlength=(
                    max_possible_gap + 1
                )
            )

            pixel_gap_histogram[
                :len(current_counts)
            ] += current_counts

        # Update the previous-valid date only where
        # the current pixel is actually valid.
        last_valid_day[
            current_valid
        ] = current_day


    # Ignore gap = 0.
    pixel_gap_histogram[0] = 0

    pixel_gap_count = int(
        pixel_gap_histogram.sum()
    )


    # ---------------------------------------------------
    # Pixel-gap statistics
    # ---------------------------------------------------

    pixel_gap_mean = histogram_mean(
        pixel_gap_histogram
    )

    pixel_gap_median = histogram_quantile(
        pixel_gap_histogram,
        0.50
    )

    pixel_gap_p75 = histogram_quantile(
        pixel_gap_histogram,
        0.75
    )

    pixel_gap_p90 = histogram_quantile(
        pixel_gap_histogram,
        0.90
    )

    pixel_gap_p95 = histogram_quantile(
        pixel_gap_histogram,
        0.95
    )

    nonzero_gap_indices = np.flatnonzero(
        pixel_gap_histogram
    )

    pixel_gap_max = (
        int(nonzero_gap_indices[-1])
        if len(nonzero_gap_indices)
        else np.nan
    )


    def fraction_above(days):
        if pixel_gap_count == 0:
            return np.nan

        return float(
            pixel_gap_histogram[
                days + 1:
            ].sum()
            / pixel_gap_count
        )


    # ---------------------------------------------------
    # Summary
    # ---------------------------------------------------

    summary = {
        'split': split_name,

        'patches': n_patches,
        'calendar_positions': n_dates,

        'first_date': (
            first_date.strftime(
                '%Y-%m-%d'
            )
        ),

        'last_date': (
            last_date.strftime(
                '%Y-%m-%d'
            )
        ),

        'date_span_days': date_span_days,

        'observations_mean': float(
            observations_per_patch.mean()
        ),

        'observations_median': float(
            np.median(
                observations_per_patch
            )
        ),

        'observations_min': int(
            observations_per_patch.min()
        ),

        'observations_max': int(
            observations_per_patch.max()
        ),

        'missing_calendar_fraction_mean': float(
            missing_fraction_per_patch.mean()
        ),

        'acquisition_gap_count': int(
            len(acquisition_gaps)
        ),

        'acquisition_gap_mean_days': float(
            acquisition_gaps.mean()
        ),

        'acquisition_gap_median_days': float(
            np.median(
                acquisition_gaps
            )
        ),

        'acquisition_gap_p90_days': float(
            np.percentile(
                acquisition_gaps,
                90
            )
        ),

        'acquisition_gap_max_days': int(
            acquisition_gaps.max()
        ),

        'pixel_gap_count': pixel_gap_count,

        'pixel_gap_mean_days': (
            pixel_gap_mean
        ),

        'pixel_gap_median_days': (
            pixel_gap_median
        ),

        'pixel_gap_p75_days': (
            pixel_gap_p75
        ),

        'pixel_gap_p90_days': (
            pixel_gap_p90
        ),

        'pixel_gap_p95_days': (
            pixel_gap_p95
        ),

        'pixel_gap_max_days': (
            pixel_gap_max
        ),

        'pixel_gap_gt_5_fraction': (
            fraction_above(5)
        ),

        'pixel_gap_gt_10_fraction': (
            fraction_above(10)
        ),

        'pixel_gap_gt_20_fraction': (
            fraction_above(20)
        ),

        'pixel_gap_gt_30_fraction': (
            fraction_above(30)
        )
    }


    return {
        'summary': summary,
        'acquisition_gaps': (
            acquisition_gaps
        ),
        'pixel_gap_histogram': (
            pixel_gap_histogram
        ),
        'observations_per_patch': (
            observations_per_patch
        )
    }

"""### 32.3 Run the analysis"""

