"""## 33. Tune the CfC elapsed-time scale

Evaluates how the numerical representation of elapsed time affects the CNN–CfC model.

The architecture, parameter count, optimization procedure, training data, and validation data remain unchanged. Only the number of calendar days represented by one CfC time unit is varied.

Three physically interpretable scales are evaluated: 5, 10, and 30 days. Model selection uses validation mean IoU exclusively. The independent test region is not accessed during this tuning procedure.
"""

TEMPORAL_IRREGULARITY_PATH = (
    RESULTS_DIR /
    'temporal_irregularity_analysis.csv'
)

