"""### 33.3 Helper for a fair training loader"""

def make_cfc_sweep_train_loader():
    set_reproducible_seed(SEED)

    generator = torch.Generator()
    generator.manual_seed(SEED)

    return DataLoader(
        train_dataset,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=NUM_WORKERS,
        pin_memory=PIN_MEMORY,
        drop_last=False,
        generator=generator
    )

"""### 33.4 Run the validation-only scale sweep"""

CFC_TIME_SCALE_SWEEP_RESULTS = []

for time_scale_days in CFC_TIME_SCALE_CANDIDATES:

    print('\n' + '=' * 70)
    print(
        'CfC GPU time-scale experiment:',
        f'{time_scale_days:.0f} days'
    )
    print('=' * 70)

    trial_config = dict(
        CNN_CFC_CONFIG
    )

    trial_config[
        'time_scale_days'
    ] = float(
        time_scale_days
    )

    trial_name = (
        'cnn_cfc_timescale_'
        f'{int(time_scale_days)}d'
    )

    trial_checkpoint_path = (
        CFC_TIME_SCALE_SWEEP_CHECKPOINT_DIR /
        f'{trial_name}_best.pt'
    )

    trial_history_path = (
        CFC_TIME_SCALE_SWEEP_DIR /
        f'{trial_name}_history.csv'
    )

    # -----------------------------------------------
    # Fresh identical initialization
    # -----------------------------------------------

    set_reproducible_seed(SEED)

    trial_model = (
        CNNCfCSegmentationModel(
            **trial_config
        ).to(DEVICE)
    )

    trial_train_loader = (
        make_cfc_sweep_train_loader()
    )

    print('Device:', DEVICE)
    print('AMP:', USE_AMP)

    print(
        'Trainable parameters:',
        count_model_parameters(
            trial_model
        )['trainable_parameters']
    )

    # -----------------------------------------------
    # Train
    # -----------------------------------------------

    trial_training_result = (
        fit_neural_model(
            model_name=trial_name,
            model=trial_model,
            model_config=trial_config,
            train_data_loader=(
                trial_train_loader
            ),
            validation_data_loader=(
                valid_loader
            ),
            criterion=(
                WEIGHTED_CRITERION
            ),
            checkpoint_path=(
                trial_checkpoint_path
            ),
            history_path=(
                trial_history_path
            ),
            maximum_epochs=(
                TRAINING_CONFIG[
                    'maximum_epochs'
                ]
            )
        )
    )

    # -----------------------------------------------
    # Evaluate selected checkpoint
    # -----------------------------------------------

    validation_metrics = evaluate_model(
        model=(
            trial_training_result[
                'model'
            ]
        ),
        data_loader=valid_loader,
        criterion=WEIGHTED_CRITERION,
        device=DEVICE
    )

    result_row = {
        'time_scale_days': float(
            time_scale_days
        ),

        'best_epoch': int(
            trial_training_result[
                'best_epoch'
            ]
        ),

        'validation_overall_accuracy': float(
            validation_metrics[
                'overall_accuracy'
            ]
        ),

        'validation_macro_f1': float(
            validation_metrics[
                'macro_f1'
            ]
        ),

        'validation_mean_iou': float(
            validation_metrics[
                'mean_iou'
            ]
        ),

        'validation_kappa': float(
            validation_metrics[
                'kappa'
            ]
        ),

        'validation_loss': float(
            validation_metrics[
                'loss'
            ]
        ),

        'training_seconds': float(
            trial_training_result[
                'total_training_seconds'
            ]
        ),

        'checkpoint_path': str(
            trial_checkpoint_path
        ),

        'device': str(DEVICE),

        'use_amp': bool(USE_AMP)
    }

    CFC_TIME_SCALE_SWEEP_RESULTS.append(
        result_row
    )

    # -----------------------------------------------
    # Save partial results immediately
    # -----------------------------------------------

    partial_df = pd.DataFrame(
        CFC_TIME_SCALE_SWEEP_RESULTS
    )

    partial_df.to_csv(
        CFC_TIME_SCALE_SWEEP_SUMMARY_PATH,
        index=False
    )

    print('\nCompleted:')
    display(
        pd.DataFrame(
            [result_row]
        )
    )

    print(
        'Partial sweep summary saved:',
        CFC_TIME_SCALE_SWEEP_SUMMARY_PATH
    )

    # -----------------------------------------------
    # Cleanup
    # -----------------------------------------------

    del trial_model
    del trial_training_result
    del trial_train_loader

    gc.collect()

    if DEVICE.type == 'cuda':
        torch.cuda.empty_cache()

