"""### 35.2 Masked temporal spatial mean"""

# -------------------------------------------------------
# Section 35.2
# Mask-aware temporal mean
# -------------------------------------------------------

def masked_temporal_spatial_mean(
    features,
    validity_weights,
    eps=1e-6
):
    """
    Parameters
    ----------
    features:
        [B, T, C, H, W]

    validity_weights:
        [B, T, 1, H, W]

    Returns
    -------
    [B, C, H, W]
    """

    weights = validity_weights.to(
        dtype=features.dtype
    )

    numerator = (
        features * weights
    ).sum(
        dim=1
    )

    denominator = weights.sum(
        dim=1
    ).clamp_min(
        eps
    )

    return (
        numerator / denominator
    )

"""### 35.3 Continuous-time latent CfC module

This implements the same principle as our previous pixel-wise CfC, but at the 13×13 latent grid.
"""

# -------------------------------------------------------
# Section 35.3
# Masked latent-grid CfC
# -------------------------------------------------------

class MaskedLatentCfC(nn.Module):

    def __init__(
        self,
        input_size,
        hidden_size,
        cfc_mode='default',
        backbone_units=32,
        backbone_layers=1,
        backbone_dropout=0.0,
        time_scale_days=5.0
    ):
        super().__init__()

        self.input_size = int(
            input_size
        )

        self.hidden_size = int(
            hidden_size
        )

        self.time_scale_days = float(
            time_scale_days
        )

        self.cell = CfCCell(
            input_size=self.input_size,

            hidden_size=self.hidden_size,

            mode=cfc_mode,

            backbone_units=(
                backbone_units
            ),

            backbone_layers=(
                backbone_layers
            ),

            backbone_dropout=(
                backbone_dropout
            )
        )


    def forward(
        self,
        features,
        valid_mask,
        delta_days
    ):
        """
        features:
            [B,T,C,H,W]

        valid_mask:
            [B,T,H,W]

        delta_days:
            [B,T,1]
        """

        B, T, C, H, W = (
            features.shape
        )

        if C != self.input_size:
            raise ValueError(
                f'Expected {self.input_size} '
                f'features, received {C}.'
            )


        # -----------------------------------------------
        # Convert latent spatial positions into a batch
        # of independent temporal trajectories.
        #
        # [B,T,C,H,W]
        #       ↓
        # [B*H*W,T,C]
        # -----------------------------------------------

        token_features = (
            features
            .permute(
                0, 3, 4, 1, 2
            )
            .reshape(
                B * H * W,
                T,
                C
            )
        )

        token_valid = (
            valid_mask
            .permute(
                0, 2, 3, 1
            )
            .reshape(
                B * H * W,
                T
            )
        )


        hidden = torch.zeros(
            (
                B * H * W,
                self.hidden_size
            ),
            device=features.device,
            dtype=features.dtype
        )

        # elapsed time since the previous
        # valid update of each latent token
        elapsed = torch.zeros(
            (
                B * H * W,
                1
            ),
            device=features.device,
            dtype=features.dtype
        )


        for t in range(T):

            dt = (
                delta_days[
                    :, t, :
                ]
                .to(
                    dtype=features.dtype
                )
                .repeat_interleave(
                    H * W,
                    dim=0
                )
            )

            elapsed = (
                elapsed + dt
            )


            current_valid = (
                token_valid[
                    :, t
                ]
                .unsqueeze(1)
            )


            # CfC receives elapsed time in the
            # selected normalized time units.
            normalized_elapsed = (
                elapsed
                / self.time_scale_days
            )


            proposed_hidden, _ = (
                self.cell(
                    token_features[
                        :, t, :
                    ],
                    hidden,
                    normalized_elapsed
                )
            )


            hidden = torch.where(
                current_valid,
                proposed_hidden,
                hidden
            )


            # Reset elapsed time only when the
            # latent state was genuinely updated.
            elapsed = torch.where(
                current_valid,
                torch.zeros_like(
                    elapsed
                ),
                elapsed
            )


        hidden_map = (
            hidden
            .reshape(
                B,
                H,
                W,
                self.hidden_size
            )
            .permute(
                0, 3, 1, 2
            )
            .contiguous()
        )

        return hidden_map

"""The official CfCCell.forward() explicitly accepts the current input, hidden state, and elapsed-time term ts, so this keeps the actual continuous-time mechanism rather than approximating the irregular timing externally.

### 35.4 Define the latent-grid CNN–CfC
"""

# -------------------------------------------------------
# Section 35.4
# Latent-grid CNN-CfC segmentation model
# -------------------------------------------------------

class LatentGridCNNCfCSegmentationModel(
    nn.Module
):

    def __init__(
        self,
        input_channels=8,

        stage0_channels=24,
        stage1_channels=32,
        latent_channels=32,

        hidden_size=32,

        n_classes=4,

        cfc_mode='default',

        backbone_units=32,
        backbone_layers=1,
        backbone_dropout=0.0,

        dropout=0.15,

        time_scale_days=5.0,

        latent_valid_threshold=0.20
    ):
        super().__init__()


        self.latent_valid_threshold = float(
            latent_valid_threshold
        )


        # ===============================================
        # Spatial encoder
        # ===============================================

        self.encoder_stage0 = nn.Sequential(

            nn.Conv2d(
                input_channels,
                stage0_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Conv2d(
                stage0_channels,
                stage0_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            )
        )


        # 50 × 50 -> 25 × 25
        self.encoder_stage1 = nn.Sequential(

            nn.Conv2d(
                stage0_channels,
                stage1_channels,
                kernel_size=3,
                stride=2,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Conv2d(
                stage1_channels,
                stage1_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            )
        )


        # 25 × 25 -> 13 × 13
        self.encoder_latent = nn.Sequential(

            nn.Conv2d(
                stage1_channels,
                latent_channels,
                kernel_size=3,
                stride=2,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Conv2d(
                latent_channels,
                latent_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            )
        )


        # ===============================================
        # Continuous-time latent dynamics
        # ===============================================

        self.temporal = MaskedLatentCfC(

            input_size=(
                latent_channels
            ),

            hidden_size=hidden_size,

            cfc_mode=cfc_mode,

            backbone_units=(
                backbone_units
            ),

            backbone_layers=(
                backbone_layers
            ),

            backbone_dropout=(
                backbone_dropout
            ),

            time_scale_days=(
                time_scale_days
            )
        )


        # ===============================================
        # Spatial decoder
        # ===============================================

        self.decoder_stage1 = nn.Sequential(

            nn.Conv2d(
                hidden_size
                + stage1_channels,

                stage1_channels,

                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Dropout2d(
                dropout
            ),

            nn.Conv2d(
                stage1_channels,
                stage1_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            )
        )


        self.decoder_stage0 = nn.Sequential(

            nn.Conv2d(
                stage1_channels
                + stage0_channels,

                stage0_channels,

                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Dropout2d(
                dropout
            ),

            nn.Conv2d(
                stage0_channels,
                stage0_channels,
                kernel_size=3,
                padding=1
            ),

            nn.ReLU(
                inplace=True
            )
        )


        self.classifier = nn.Conv2d(
            stage0_channels,
            n_classes,
            kernel_size=1
        )


    def forward(
        self,
        X,
        time_mask,
        valid_pixel_mask,
        delta_days
    ):

        B, T, C, H, W = X.shape


        # ===============================================
        # Encode all dates efficiently
        # ===============================================

        x = X.reshape(
            B * T,
            C,
            H,
            W
        )


        stage0 = (
            self.encoder_stage0(
                x
            )
        )

        stage1 = (
            self.encoder_stage1(
                stage0
            )
        )

        latent = (
            self.encoder_latent(
                stage1
            )
        )


        _, C0, H0, W0 = (
            stage0.shape
        )

        _, C1, H1, W1 = (
            stage1.shape
        )

        _, CL, HL, WL = (
            latent.shape
        )


        stage0 = stage0.reshape(
            B,
            T,
            C0,
            H0,
            W0
        )

        stage1 = stage1.reshape(
            B,
            T,
            C1,
            H1,
            W1
        )

        latent = latent.reshape(
            B,
            T,
            CL,
            HL,
            WL
        )


        # ===============================================
        # Downsample validity fractions
        # ===============================================

        pixel_valid = (
            valid_pixel_mask
            .float()
            .reshape(
                B * T,
                1,
                H,
                W
            )
        )


        valid0 = F.interpolate(
            pixel_valid,
            size=(H0, W0),
            mode='area'
        )

        valid1 = F.interpolate(
            pixel_valid,
            size=(H1, W1),
            mode='area'
        )

        valid_latent_fraction = (
            F.interpolate(
                pixel_valid,
                size=(HL, WL),
                mode='area'
            )
        )


        valid0 = valid0.reshape(
            B,
            T,
            1,
            H0,
            W0
        )

        valid1 = valid1.reshape(
            B,
            T,
            1,
            H1,
            W1
        )

        valid_latent_fraction = (
            valid_latent_fraction
            .reshape(
                B,
                T,
                1,
                HL,
                WL
            )
        )


        # Patch-level temporal availability.
        temporal_available = (
            time_mask
            .float()
            .reshape(
                B,
                T,
                1,
                1,
                1
            )
        )


        valid0 = (
            valid0
            * temporal_available
        )

        valid1 = (
            valid1
            * temporal_available
        )

        valid_latent_fraction = (
            valid_latent_fraction
            * temporal_available
        )


        # ===============================================
        # Mask-aware skip representations
        # ===============================================

        skip0 = (
            masked_temporal_spatial_mean(
                stage0,
                valid0
            )
        )

        skip1 = (
            masked_temporal_spatial_mean(
                stage1,
                valid1
            )
        )


        # ===============================================
        # Latent token validity
        # ===============================================

        latent_valid = (
            valid_latent_fraction[
                :, :, 0
            ]
            >= self.latent_valid_threshold
        )


        # ===============================================
        # CfC latent dynamics
        # ===============================================

        latent_state = (
            self.temporal(
                features=latent,

                valid_mask=latent_valid,

                delta_days=delta_days
            )
        )


        # ===============================================
        # Decode 13 -> 25
        # ===============================================

        decoded1 = F.interpolate(
            latent_state,

            size=(
                H1,
                W1
            ),

            mode='bilinear',

            align_corners=False
        )


        decoded1 = torch.cat(
            [
                decoded1,
                skip1
            ],
            dim=1
        )


        decoded1 = (
            self.decoder_stage1(
                decoded1
            )
        )


        # ===============================================
        # Decode 25 -> 50
        # ===============================================

        decoded0 = F.interpolate(
            decoded1,

            size=(
                H0,
                W0
            ),

            mode='bilinear',

            align_corners=False
        )


        decoded0 = torch.cat(
            [
                decoded0,
                skip0
            ],
            dim=1
        )


        decoded0 = (
            self.decoder_stage0(
                decoded0
            )
        )


        logits = self.classifier(
            decoded0
        )

        return logits

"""### 35.5 Make forward_model() support the new architecture"""

# -------------------------------------------------------
# Section 35.5
# Add latent-grid model support
# -------------------------------------------------------

_original_forward_model = (
    forward_model
)


def forward_model(
    model,
    batch
):

    if isinstance(
        model,
        LatentGridCNNCfCSegmentationModel
    ):

        return model(
            X=batch['X'],

            time_mask=batch[
                'time_mask'
            ],

            valid_pixel_mask=batch[
                'valid_pixel_mask'
            ],

            delta_days=batch[
                'delta_days'
            ]
        )

    return _original_forward_model(
        model,
        batch
    )


print(
    'Latent-grid model support added '
    'to forward_model().'
)

