"""### 35.8 Verify that elapsed time still affects the model

This is important. We do not want the new compressed architecture to accidentally stop using delta_days.
"""

# -------------------------------------------------------
# Section 35.8
# Continuous-time sensitivity check
# -------------------------------------------------------

latent_cfc_model.eval()


with torch.no_grad():

    with amp_context:

        logits_original_time = (
            latent_cfc_model(
                X=sample_batch['X'],

                time_mask=sample_batch[
                    'time_mask'
                ],

                valid_pixel_mask=sample_batch[
                    'valid_pixel_mask'
                ],

                delta_days=sample_batch[
                    'delta_days'
                ]
            )
        )


        doubled_delta = (
            sample_batch[
                'delta_days'
            ].clone()
        )

        positive_gap_mask = (
            doubled_delta > 0
        )

        doubled_delta[
            positive_gap_mask
        ] *= 2.0


        logits_doubled_time = (
            latent_cfc_model(
                X=sample_batch['X'],

                time_mask=sample_batch[
                    'time_mask'
                ],

                valid_pixel_mask=sample_batch[
                    'valid_pixel_mask'
                ],

                delta_days=doubled_delta
            )
        )


time_sensitivity = float(
    (
        logits_original_time
        - logits_doubled_time
    )
    .abs()
    .mean()
    .item()
)


print(
    'Mean absolute output change '
    'after doubling positive gaps:'
)

print(
    time_sensitivity
)

assert (
    time_sensitivity > 0
)

print(
    'Continuous-time sensitivity '
    'confirmed.'
)

