"""## 37. Latent-grid CNN–LTC

Now we should apply exactly the same spatial encoder and decoder to LTC.

This is particularly important because the original LTC performed the ODE recurrence over 2,500 spatial trajectories. The new model will perform it over only 169 latent trajectories.

The official ncps LTCCell accepts an explicit elapsed_time and configurable ode_unfolds, and LTC also supports wired recurrent structures. We will initially keep ode_unfolds=6, matching the original LTC configuration, so we do not simultaneously change too many factors.

### 37.1 Imports and configuration
"""

# -------------------------------------------------------
# Section 37.1
# Latent-grid CNN-LTC configuration
# -------------------------------------------------------

from ncps.torch import LTCCell
from ncps.wirings import FullyConnected


LATENT_LTC_NAME = (
    'latent_grid_cnn_ltc'
)


LATENT_LTC_CONFIG = {
    'input_channels': 8,

    'stage0_channels': 24,
    'stage1_channels': 32,
    'latent_channels': 32,

    'hidden_size': 32,

    'n_classes': 4,

    'input_mapping': 'affine',
    'output_mapping': 'affine',

    # Keep the original LTC numerical resolution
    # for the first architecture experiment.
    'ode_unfolds': 6,

    'implicit_param_constraints': True,

    'wiring_seed': 1111,

    'dropout': 0.15,

    # Selected continuous-time scale.
    'time_scale_days': 5.0,

    # Same convention as the original LTC.
    'minimum_elapsed_days': 1.0,

    # Same latent validity criterion as latent CfC.
    'latent_valid_threshold': 0.20
}


print(
    'Latent-grid CNN-LTC configuration:'
)

for key, value in (
    LATENT_LTC_CONFIG.items()
):
    print(
        f'{key}: {value}'
    )

"""### 37.2 Define the masked latent LTC

The LTC calculations remain in float32 even though the rest of the model can use AMP. We already found this necessary for numerical stability in the original LTC.
"""

# -------------------------------------------------------
# Section 37.2
# Masked latent-grid LTC
# -------------------------------------------------------

class MaskedLatentLTC(nn.Module):

    def __init__(
        self,
        input_size,
        hidden_size,

        input_mapping='affine',
        output_mapping='affine',

        ode_unfolds=6,

        implicit_param_constraints=True,

        wiring_seed=1111,

        time_scale_days=5.0,

        minimum_elapsed_days=1.0
    ):
        super().__init__()


        self.input_size = int(
            input_size
        )

        self.hidden_size = int(
            hidden_size
        )

        self.time_scale_days = float(
            time_scale_days
        )

        self.minimum_elapsed_days = float(
            minimum_elapsed_days
        )


        # ------------------------------------------------
        # Fully connected LTC wiring.
        #
        # output_dim = hidden_size so the temporal
        # representation retains 32 latent channels.
        # ------------------------------------------------

        self.wiring = FullyConnected(
            units=self.hidden_size,

            output_dim=self.hidden_size,

            erev_init_seed=wiring_seed,

            self_connections=True
        )


        self.cell = LTCCell(
            wiring=self.wiring,

            in_features=self.input_size,

            input_mapping=input_mapping,

            output_mapping=output_mapping,

            ode_unfolds=ode_unfolds,

            epsilon=1e-8,

            implicit_param_constraints=(
                implicit_param_constraints
            )
        )


    def forward(
        self,
        features,
        valid_mask,
        delta_days
    ):
        """
        features:
            [B,T,C,H,W]

        valid_mask:
            [B,T,H,W]

        delta_days:
            [B,T,1]
        """

        B, T, C, H, W = (
            features.shape
        )


        if C != self.input_size:

            raise ValueError(
                f'Expected {self.input_size} '
                f'features, received {C}.'
            )


        # ------------------------------------------------
        # Convert latent spatial positions to temporal
        # trajectories.
        #
        # [B,T,C,H,W]
        #       ->
        # [B*H*W,T,C]
        # ------------------------------------------------

        token_features = (
            features
            .permute(
                0, 3, 4, 1, 2
            )
            .reshape(
                B * H * W,
                T,
                C
            )
            .float()
        )


        token_valid = (
            valid_mask
            .permute(
                0, 2, 3, 1
            )
            .reshape(
                B * H * W,
                T
            )
        )


        # LTC state kept explicitly in float32.
        hidden = torch.zeros(
            (
                B * H * W,
                self.hidden_size
            ),

            device=features.device,

            dtype=torch.float32
        )


        elapsed_days = torch.zeros(
            (
                B * H * W,
                1
            ),

            device=features.device,

            dtype=torch.float32
        )


        # ------------------------------------------------
        # Continuous-time recurrence
        # ------------------------------------------------

        for t in range(T):

            dt = (
                delta_days[
                    :, t, :
                ]
                .float()
                .repeat_interleave(
                    H * W,
                    dim=0
                )
            )


            elapsed_days = (
                elapsed_days + dt
            )


            current_valid = (
                token_valid[
                    :, t
                ]
                .unsqueeze(1)
            )


            # Avoid a zero integration interval for
            # the first valid observation.
            effective_elapsed_days = (
                elapsed_days.clamp_min(
                    self.minimum_elapsed_days
                )
            )


            normalized_elapsed = (
                effective_elapsed_days
                / self.time_scale_days
            )


            # LTC numerical integration remains float32.
            if features.device.type == 'cuda':

                ltc_context = torch.autocast(
                    device_type='cuda',
                    enabled=False
                )

            else:

                ltc_context = nullcontext()


            with ltc_context:

                proposed_output, proposed_hidden = (
                    self.cell(
                        token_features[
                            :, t, :
                        ],

                        hidden,

                        elapsed_time=(
                            normalized_elapsed
                        )
                    )
                )


            # State changes only for actually valid
            # latent observations.
            hidden = torch.where(
                current_valid,
                proposed_hidden,
                hidden
            )


            # Reset elapsed time only after a true
            # recurrent update.
            elapsed_days = torch.where(
                current_valid,

                torch.zeros_like(
                    elapsed_days
                ),

                elapsed_days
            )


        hidden_map = (
            hidden
            .reshape(
                B,
                H,
                W,
                self.hidden_size
            )
            .permute(
                0, 3, 1, 2
            )
            .contiguous()
        )


        return hidden_map

"""### 37.3 Define the segmentation model

We can reuse the exact latent CfC spatial architecture and only replace its temporal module.
"""

# -------------------------------------------------------
# Section 37.3
# Latent-grid CNN-LTC segmentation model
# -------------------------------------------------------

class LatentGridCNNLTCSegmentationModel(
    LatentGridCNNCfCSegmentationModel
):

    def __init__(
        self,

        input_channels=8,

        stage0_channels=24,
        stage1_channels=32,
        latent_channels=32,

        hidden_size=32,

        n_classes=4,

        input_mapping='affine',
        output_mapping='affine',

        ode_unfolds=6,

        implicit_param_constraints=True,

        wiring_seed=1111,

        dropout=0.15,

        time_scale_days=5.0,

        minimum_elapsed_days=1.0,

        latent_valid_threshold=0.20
    ):


        # ------------------------------------------------
        # Build the identical encoder / decoder used by
        # the latent-grid CfC.
        # ------------------------------------------------

        super().__init__(

            input_channels=(
                input_channels
            ),

            stage0_channels=(
                stage0_channels
            ),

            stage1_channels=(
                stage1_channels
            ),

            latent_channels=(
                latent_channels
            ),

            hidden_size=(
                hidden_size
            ),

            n_classes=(
                n_classes
            ),

            # Temporary CfC module is replaced below.
            cfc_mode='default',

            backbone_units=32,
            backbone_layers=1,
            backbone_dropout=0.0,

            dropout=dropout,

            time_scale_days=(
                time_scale_days
            ),

            latent_valid_threshold=(
                latent_valid_threshold
            )
        )


        # ------------------------------------------------
        # Replace only the temporal component.
        # ------------------------------------------------

        self.temporal = MaskedLatentLTC(

            input_size=(
                latent_channels
            ),

            hidden_size=(
                hidden_size
            ),

            input_mapping=(
                input_mapping
            ),

            output_mapping=(
                output_mapping
            ),

            ode_unfolds=(
                ode_unfolds
            ),

            implicit_param_constraints=(
                implicit_param_constraints
            ),

            wiring_seed=(
                wiring_seed
            ),

            time_scale_days=(
                time_scale_days
            ),

            minimum_elapsed_days=(
                minimum_elapsed_days
            )
        )

