"""### 37.8 Measure LTC state sensitivity before the decoder"""

# -------------------------------------------------------
# Section 37.8
# Diagnose LTC time sensitivity at latent-state level
# -------------------------------------------------------

@torch.no_grad()
def extract_latent_temporal_inputs(
    model,
    batch
):
    """
    Reproduce the encoder and validity processing used
    before the latent temporal module.
    """

    X = batch['X']
    time_mask = batch['time_mask']
    valid_pixel_mask = batch[
        'valid_pixel_mask'
    ]

    B, T, C, H, W = X.shape

    # ---------------------------------------------------
    # Spatial encoder
    # ---------------------------------------------------

    x = X.reshape(
        B * T,
        C,
        H,
        W
    )

    stage0 = model.encoder_stage0(
        x
    )

    stage1 = model.encoder_stage1(
        stage0
    )

    latent = model.encoder_latent(
        stage1
    )

    _, CL, HL, WL = latent.shape

    latent = latent.reshape(
        B,
        T,
        CL,
        HL,
        WL
    )

    # ---------------------------------------------------
    # Latent validity
    # ---------------------------------------------------

    pixel_valid = (
        valid_pixel_mask
        .float()
        .reshape(
            B * T,
            1,
            H,
            W
        )
    )

    valid_latent_fraction = (
        F.interpolate(
            pixel_valid,
            size=(HL, WL),
            mode='area'
        )
    )

    valid_latent_fraction = (
        valid_latent_fraction
        .reshape(
            B,
            T,
            1,
            HL,
            WL
        )
    )

    temporal_available = (
        time_mask
        .float()
        .reshape(
            B,
            T,
            1,
            1,
            1
        )
    )

    valid_latent_fraction = (
        valid_latent_fraction
        * temporal_available
    )

    latent_valid = (
        valid_latent_fraction[
            :, :, 0
        ]
        >= model.latent_valid_threshold
    )

    return (
        latent,
        latent_valid
    )

latent_ltc_model.eval()

sample_batch = next(
    iter(train_loader)
)

sample_batch = move_batch_to_device(
    sample_batch,
    DEVICE
)


with torch.no_grad():

    latent_features, latent_valid = (
        extract_latent_temporal_inputs(
            latent_ltc_model,
            sample_batch
        )
    )


    # Original temporal gaps
    latent_state_original = (
        latent_ltc_model.temporal(
            features=latent_features,

            valid_mask=latent_valid,

            delta_days=sample_batch[
                'delta_days'
            ]
        )
    )


    # Double all positive gaps
    doubled_delta = (
        sample_batch[
            'delta_days'
        ].clone()
    )

    doubled_delta[
        doubled_delta > 0
    ] *= 2.0


    latent_state_doubled = (
        latent_ltc_model.temporal(
            features=latent_features,

            valid_mask=latent_valid,

            delta_days=doubled_delta
        )
    )


latent_state_sensitivity = float(
    (
        latent_state_original
        - latent_state_doubled
    )
    .abs()
    .mean()
    .item()
)


latent_state_max_change = float(
    (
        latent_state_original
        - latent_state_doubled
    )
    .abs()
    .max()
    .item()
)


print(
    'Latent LTC state sensitivity:',
    latent_state_sensitivity
)

print(
    'Maximum latent-state change:',
    latent_state_max_change
)

print(
    'Final-logit sensitivity:',
    latent_ltc_time_sensitivity
)

print(
    'State/logit sensitivity ratio:',
    (
        latent_state_sensitivity
        /
        max(
            latent_ltc_time_sensitivity,
            1e-12
        )
    )
)

"""### 37.9 Diagnose LTC time-scale response without training"""

# -------------------------------------------------------
# Section 37.9
# LTC initial time-scale sensitivity diagnostic
# -------------------------------------------------------

LTC_DIAGNOSTIC_TIME_SCALES = [
    1.0,
    5.0,
    10.0,
    30.0
]

ltc_time_scale_diagnostic_rows = []


for time_scale_days in (
    LTC_DIAGNOSTIC_TIME_SCALES
):

    print(
        '\nTesting LTC time scale:',
        time_scale_days,
        'days'
    )

    diagnostic_config = dict(
        LATENT_LTC_CONFIG
    )

    diagnostic_config[
        'time_scale_days'
    ] = float(
        time_scale_days
    )

    set_reproducible_seed(
        SEED
    )

    diagnostic_model = (
        LatentGridCNNLTCSegmentationModel(
            **diagnostic_config
        )
        .to(
            DEVICE
        )
    )

    diagnostic_model.eval()


    with torch.no_grad():

        latent_features, latent_valid = (
            extract_latent_temporal_inputs(
                diagnostic_model,
                sample_batch
            )
        )


        state_original = (
            diagnostic_model.temporal(
                features=latent_features,

                valid_mask=latent_valid,

                delta_days=sample_batch[
                    'delta_days'
                ]
            )
        )


        diagnostic_doubled_delta = (
            sample_batch[
                'delta_days'
            ].clone()
        )

        diagnostic_doubled_delta[
            diagnostic_doubled_delta > 0
        ] *= 2.0


        state_doubled = (
            diagnostic_model.temporal(
                features=latent_features,

                valid_mask=latent_valid,

                delta_days=(
                    diagnostic_doubled_delta
                )
            )
        )


        with torch.autocast(
            device_type='cuda',
            dtype=torch.float16
        ):

            logits_original = (
                diagnostic_model(
                    X=sample_batch['X'],

                    time_mask=sample_batch[
                        'time_mask'
                    ],

                    valid_pixel_mask=(
                        sample_batch[
                            'valid_pixel_mask'
                        ]
                    ),

                    delta_days=sample_batch[
                        'delta_days'
                    ]
                )
            )


            logits_doubled = (
                diagnostic_model(
                    X=sample_batch['X'],

                    time_mask=sample_batch[
                        'time_mask'
                    ],

                    valid_pixel_mask=(
                        sample_batch[
                            'valid_pixel_mask'
                        ]
                    ),

                    delta_days=(
                        diagnostic_doubled_delta
                    )
                )
            )


    state_sensitivity = float(
        (
            state_original
            - state_doubled
        )
        .abs()
        .mean()
        .item()
    )

    logit_sensitivity = float(
        (
            logits_original
            - logits_doubled
        )
        .abs()
        .mean()
        .item()
    )


    ltc_time_scale_diagnostic_rows.append({
        'time_scale_days': (
            time_scale_days
        ),

        'latent_state_sensitivity': (
            state_sensitivity
        ),

        'logit_sensitivity': (
            logit_sensitivity
        )
    })


    del diagnostic_model

    gc.collect()

    if DEVICE.type == 'cuda':
        torch.cuda.empty_cache()


