"""## 39. Matched latent-grid LSTM and GRU

same input
same CNN encoder
same 13×13 latent representation
same validity handling
same decoder
same loss/training procedure

             ↓ temporal unit only ↓

LSTM | GRU | CfC | LTC

### 39.1 Define masked latent LSTM and GRU
"""

# -------------------------------------------------------
# Section 39.1
# Matched latent-grid recurrent temporal modules
# -------------------------------------------------------

class MaskedLatentLSTM(nn.Module):

    def __init__(
        self,
        input_size,
        hidden_size
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.cell = nn.LSTMCell(
            input_size=self.input_size,
            hidden_size=self.hidden_size
        )


    def forward(
        self,
        features,
        valid_mask,
        delta_days=None
    ):
        """
        features:
            [B,T,C,H,W]

        valid_mask:
            [B,T,H,W]

        delta_days:
            accepted only for common interface;
            standard LSTM does not use elapsed time.
        """

        B, T, C, H, W = features.shape

        token_features = (
            features
            .permute(0, 3, 4, 1, 2)
            .reshape(
                B * H * W,
                T,
                C
            )
        )

        token_valid = (
            valid_mask
            .permute(0, 2, 3, 1)
            .reshape(
                B * H * W,
                T
            )
        )

        hidden = torch.zeros(
            B * H * W,
            self.hidden_size,
            device=features.device,
            dtype=features.dtype
        )

        cell_state = torch.zeros_like(
            hidden
        )


        for t in range(T):

            proposed_hidden, proposed_cell = (
                self.cell(
                    token_features[:, t, :],
                    (
                        hidden,
                        cell_state
                    )
                )
            )

            current_valid = (
                token_valid[:, t]
                .unsqueeze(1)
            )

            hidden = torch.where(
                current_valid,
                proposed_hidden,
                hidden
            )

            cell_state = torch.where(
                current_valid,
                proposed_cell,
                cell_state
            )


        hidden_map = (
            hidden
            .reshape(
                B,
                H,
                W,
                self.hidden_size
            )
            .permute(
                0, 3, 1, 2
            )
            .contiguous()
        )

        return hidden_map


class MaskedLatentGRU(nn.Module):

    def __init__(
        self,
        input_size,
        hidden_size
    ):
        super().__init__()

        self.input_size = int(input_size)
        self.hidden_size = int(hidden_size)

        self.cell = nn.GRUCell(
            input_size=self.input_size,
            hidden_size=self.hidden_size
        )


    def forward(
        self,
        features,
        valid_mask,
        delta_days=None
    ):
        """
        Same interface as the continuous-time modules,
        but standard GRU does not use delta_days.
        """

        B, T, C, H, W = features.shape

        token_features = (
            features
            .permute(0, 3, 4, 1, 2)
            .reshape(
                B * H * W,
                T,
                C
            )
        )

        token_valid = (
            valid_mask
            .permute(0, 2, 3, 1)
            .reshape(
                B * H * W,
                T
            )
        )

        hidden = torch.zeros(
            B * H * W,
            self.hidden_size,
            device=features.device,
            dtype=features.dtype
        )


        for t in range(T):

            proposed_hidden = (
                self.cell(
                    token_features[:, t, :],
                    hidden
                )
            )

            current_valid = (
                token_valid[:, t]
                .unsqueeze(1)
            )

            hidden = torch.where(
                current_valid,
                proposed_hidden,
                hidden
            )


        hidden_map = (
            hidden
            .reshape(
                B,
                H,
                W,
                self.hidden_size
            )
            .permute(
                0, 3, 1, 2
            )
            .contiguous()
        )

        return hidden_map

"""### 39.2 Define matched segmentation models

They inherit the same latent-grid CNN architecture as the CfC model and replace only the temporal module.
"""

# -------------------------------------------------------
# Section 39.2
# Matched latent-grid CNN-LSTM / CNN-GRU
# -------------------------------------------------------

class LatentGridCNNLSTMSegmentationModel(
    LatentGridCNNCfCSegmentationModel
):

    def __init__(
        self,
        input_channels=8,
        stage0_channels=24,
        stage1_channels=32,
        latent_channels=32,
        hidden_size=32,
        n_classes=4,
        dropout=0.15,
        latent_valid_threshold=0.20
    ):

        super().__init__(
            input_channels=input_channels,
            stage0_channels=stage0_channels,
            stage1_channels=stage1_channels,
            latent_channels=latent_channels,
            hidden_size=hidden_size,
            n_classes=n_classes,

            # Temporary CfC is immediately replaced.
            cfc_mode='default',
            backbone_units=32,
            backbone_layers=1,
            backbone_dropout=0.0,

            dropout=dropout,
            time_scale_days=5.0,

            latent_valid_threshold=(
                latent_valid_threshold
            )
        )

        self.temporal = MaskedLatentLSTM(
            input_size=latent_channels,
            hidden_size=hidden_size
        )


class LatentGridCNNGRUSegmentationModel(
    LatentGridCNNCfCSegmentationModel
):

    def __init__(
        self,
        input_channels=8,
        stage0_channels=24,
        stage1_channels=32,
        latent_channels=32,
        hidden_size=32,
        n_classes=4,
        dropout=0.15,
        latent_valid_threshold=0.20
    ):

        super().__init__(
            input_channels=input_channels,
            stage0_channels=stage0_channels,
            stage1_channels=stage1_channels,
            latent_channels=latent_channels,
            hidden_size=hidden_size,
            n_classes=n_classes,

            cfc_mode='default',
            backbone_units=32,
            backbone_layers=1,
            backbone_dropout=0.0,

            dropout=dropout,
            time_scale_days=5.0,

            latent_valid_threshold=(
                latent_valid_threshold
            )
        )

        self.temporal = MaskedLatentGRU(
            input_size=latent_channels,
            hidden_size=hidden_size
        )

