"""### 39.4 Parameter counts and smoke tests"""

# -------------------------------------------------------
# Section 39.4
# Matched-model smoke tests
# -------------------------------------------------------

matched_smoke_rows = []

sample_batch = next(
    iter(valid_loader)
)

sample_batch = move_batch_to_device(
    sample_batch,
    DEVICE
)


MATCHED_MODEL_CLASSES = {
    'latent_lstm':
        LatentGridCNNLSTMSegmentationModel,

    'latent_gru':
        LatentGridCNNGRUSegmentationModel
}


for model_name, model_class in (
    MATCHED_MODEL_CLASSES.items()
):

    set_reproducible_seed(SEED)

    model = (
        model_class(
            **LATENT_RECURRENT_COMMON_CONFIG
        )
        .to(DEVICE)
    )

    parameter_info = (
        count_model_parameters(
            model
        )
    )

    model.eval()

    if DEVICE.type == 'cuda':
        torch.cuda.synchronize()

    start = time.perf_counter()

    with torch.no_grad():

        amp_context = (
            torch.autocast(
                device_type='cuda',
                dtype=torch.float16
            )
            if USE_AMP
            else nullcontext()
        )

        with amp_context:

            logits = forward_model(
                model,
                sample_batch
            )

            loss = WEIGHTED_CRITERION(
                logits,
                sample_batch['y']
            )

    if DEVICE.type == 'cuda':
        torch.cuda.synchronize()

    forward_seconds = (
        time.perf_counter()
        - start
    )


    matched_smoke_rows.append({
        'model': model_name,

        'total_parameters': (
            parameter_info[
                'total_parameters'
            ]
        ),

        'trainable_parameters': (
            parameter_info[
                'trainable_parameters'
            ]
        ),

        'forward_seconds': (
            forward_seconds
        ),

        'loss': float(
            loss.item()
        ),

        'finite': bool(
            torch.isfinite(
                logits
            ).all().item()
        )
    })


    del model

    gc.collect()

    if DEVICE.type == 'cuda':
        torch.cuda.empty_cache()


matched_smoke_df = pd.DataFrame(
    matched_smoke_rows
)

display(
    matched_smoke_df
)

assert matched_smoke_df[
    'finite'
].all()

print(
    'Matched latent recurrent '
    'models passed smoke tests.'
)

