def make_matched_train_loader():

    set_reproducible_seed(SEED)

    generator = torch.Generator()
    generator.manual_seed(SEED)

    return DataLoader(
        train_dataset,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=NUM_WORKERS,
        pin_memory=PIN_MEMORY,
        drop_last=False,
        generator=generator
    )


