"""## 41. Does CfC actually use the irregular time gaps?

### 41.1 Equal-spacing validation dataset
"""

# -------------------------------------------------------
# Section 41.1
# Equal-spacing temporal-control dataset
# -------------------------------------------------------

class EqualSpacingDataset(Dataset):

    def __init__(
        self,
        base_dataset,
        fixed_delta_days=5.0
    ):
        self.base_dataset = base_dataset

        self.fixed_delta_days = float(
            fixed_delta_days
        )


    def __len__(self):

        return len(
            self.base_dataset
        )


    def __getitem__(self, index):

        sample = dict(
            self.base_dataset[index]
        )

        delta_days = (
            sample[
                'delta_days'
            ].clone()
        )

        # Preserve zeros:
        # - first observation
        # - absent calendar positions
        #
        # Replace only real positive temporal intervals.
        delta_days[
            delta_days > 0
        ] = self.fixed_delta_days

        sample[
            'delta_days'
        ] = delta_days

        return sample


EQUAL_DELTA_DAYS = 5.0


valid_equal_spacing_dataset = (
    EqualSpacingDataset(
        valid_dataset,
        fixed_delta_days=(
            EQUAL_DELTA_DAYS
        )
    )
)


valid_equal_spacing_loader = (
    DataLoader(
        valid_equal_spacing_dataset,

        batch_size=BATCH_SIZE,

        shuffle=False,

        num_workers=NUM_WORKERS,

        pin_memory=PIN_MEMORY,

        drop_last=False
    )
)


original_sample = valid_dataset[0]

equal_sample = (
    valid_equal_spacing_dataset[0]
)


print(
    'Original positive deltas:',
    torch.unique(
        original_sample[
            'delta_days'
        ][
            original_sample[
                'delta_days'
            ] > 0
        ]
    )
)

print(
    'Equal-spacing positive deltas:',
    torch.unique(
        equal_sample[
            'delta_days'
        ][
            equal_sample[
                'delta_days'
            ] > 0
        ]
    )
)


assert torch.all(
    equal_sample[
        'delta_days'
    ][
        equal_sample[
            'delta_days'
        ] > 0
    ] == EQUAL_DELTA_DAYS
)

print(
    'Equal-spacing control ready.'
)

