"""## 42. Missing-observation robustness

### 42.1 Sparse-observation dataset
"""

# -------------------------------------------------------
# Section 42.1
# Controlled missing-observation dataset
# -------------------------------------------------------

class SparseObservationDataset(Dataset):

    def __init__(
        self,
        base_dataset,
        retain_fraction,
        mask_seed
    ):

        self.base_dataset = base_dataset

        self.retain_fraction = float(
            retain_fraction
        )

        self.mask_seed = int(
            mask_seed
        )

        if not (
            0.0 < self.retain_fraction <= 1.0
        ):
            raise ValueError(
                'retain_fraction must be in (0, 1].'
            )

        self.keep_masks = []


        for index in range(
            len(base_dataset)
        ):

            sample = base_dataset[index]

            time_mask = (
                sample[
                    'time_mask'
                ]
                .cpu()
                .numpy()
                > 0
            )

            observed_indices = np.flatnonzero(
                time_mask
            )

            n_observed = len(
                observed_indices
            )


            if n_observed == 0:

                raise RuntimeError(
                    'Patch with no observations.'
                )


            if self.retain_fraction >= 1.0:

                n_keep = n_observed

            else:

                n_keep = int(
                    round(
                        n_observed
                        * self.retain_fraction
                    )
                )

                # Preserve at least first + last.
                n_keep = max(
                    2,
                    n_keep
                )

                n_keep = min(
                    n_keep,
                    n_observed
                )


            keep_mask = np.zeros_like(
                time_mask,
                dtype=bool
            )


            if n_keep >= n_observed:

                keep_mask[
                    observed_indices
                ] = True

            else:

                # Preserve temporal extent.
                first_index = (
                    observed_indices[0]
                )

                last_index = (
                    observed_indices[-1]
                )

                keep_mask[
                    first_index
                ] = True

                keep_mask[
                    last_index
                ] = True


                middle_indices = (
                    observed_indices[1:-1]
                )

                n_middle_keep = (
                    n_keep - 2
                )


                if n_middle_keep > 0:

                    rng = np.random.default_rng(
                        self.mask_seed
                        + index * 1009
                    )

                    selected = rng.choice(
                        middle_indices,
                        size=n_middle_keep,
                        replace=False
                    )

                    keep_mask[
                        selected
                    ] = True


            self.keep_masks.append(
                keep_mask
            )


    def __len__(self):

        return len(
            self.base_dataset
        )


    def __getitem__(
        self,
        index
    ):

        original = (
            self.base_dataset[index]
        )


        # Clone tensor fields.
        sample = {}

        for key, value in (
            original.items()
        ):

            if torch.is_tensor(value):

                sample[key] = (
                    value.clone()
                )

            else:

                sample[key] = value


        available = (
            sample[
                'time_mask'
            ] > 0
        )


        keep = torch.from_numpy(
            self.keep_masks[index]
        ).to(
            dtype=torch.bool
        )


        drop = (
            available
            & (~keep)
        )


        # -----------------------------------------------
        # Remove observation contents
        # -----------------------------------------------

        sample[
            'X'
        ][drop] = 0.0


        sample[
            'time_mask'
        ][drop] = 0.0


        sample[
            'valid_pixel_mask'
        ][drop] = False


        sample[
            'observation_valid_fraction'
        ][drop] = 0.0


        # IMPORTANT:
        # Do NOT zero delta_days.
        #
        # CfC must accumulate elapsed time through a
        # deliberately removed acquisition.


        sample[
            'n_observations'
        ] = torch.tensor(
            int(
                sample[
                    'time_mask'
                ].sum().item()
            ),
            dtype=torch.long
        )


        return sample

"""### 42.2 Verify the removal logic"""

