"""## 43. Paired robustness analysis

### 43.1 Paired CfC comparisons
"""

# -------------------------------------------------------
# Section 43.1
# Paired robustness comparison
# -------------------------------------------------------

robustness_df = pd.read_csv(
    ROBUSTNESS_RESULTS_PATH
)


cfc_df = (
    robustness_df[
        robustness_df['model'] == 'CfC'
    ][
        [
            'training_seed',
            'retain_fraction',
            'mask_seed',
            'mean_iou'
        ]
    ]
    .rename(
        columns={
            'mean_iou': 'cfc_miou'
        }
    )
)


PAIRWISE_ROBUSTNESS_ROWS = []


for baseline_name in [
    'LSTM',
    'GRU'
]:

    baseline_df = (
        robustness_df[
            robustness_df[
                'model'
            ] == baseline_name
        ][
            [
                'training_seed',
                'retain_fraction',
                'mask_seed',
                'mean_iou'
            ]
        ]
        .rename(
            columns={
                'mean_iou':
                    'baseline_miou'
            }
        )
    )


    paired = cfc_df.merge(
        baseline_df,

        on=[
            'training_seed',
            'retain_fraction',
            'mask_seed'
        ],

        how='inner'
    )


    paired[
        'difference'
    ] = (
        paired[
            'cfc_miou'
        ]
        -
        paired[
            'baseline_miou'
        ]
    )


    for retain_fraction, group in (
        paired.groupby(
            'retain_fraction'
        )
    ):

        PAIRWISE_ROBUSTNESS_ROWS.append({

            'baseline':
                baseline_name,

            'retain_fraction':
                float(
                    retain_fraction
                ),

            'n_pairs':
                len(group),

            'mean_cfc_minus_baseline':
                float(
                    group[
                        'difference'
                    ].mean()
                ),

            'median_cfc_minus_baseline':
                float(
                    group[
                        'difference'
                    ].median()
                ),

            'cfc_wins':
                int(
                    (
                        group[
                            'difference'
                        ] > 0
                    ).sum()
                ),

            'ties':
                int(
                    np.isclose(
                        group[
                            'difference'
                        ],
                        0.0,
                        atol=1e-8
                    ).sum()
                ),

            'baseline_wins':
                int(
                    (
                        group[
                            'difference'
                        ] < 0
                    ).sum()
                )
        })


paired_robustness_summary_df = (
    pd.DataFrame(
        PAIRWISE_ROBUSTNESS_ROWS
    )
    .sort_values(
        [
            'retain_fraction',
            'baseline'
        ],
        ascending=[
            False,
            True
        ]
    )
    .reset_index(
        drop=True
    )
)


display(
    paired_robustness_summary_df
)

"""### 43.2 Overall retention-curve score"""

# -------------------------------------------------------
# Section 43.2
# Area under the observation-retention curve
# -------------------------------------------------------

curve_rows = []


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    model_df = (
        robustness_summary_df[
            robustness_summary_df[
                'model'
            ] == model_name
        ]
        .sort_values(
            'retain_fraction'
        )
    )


    x = model_df[
        'retain_fraction'
    ].to_numpy()

    y = model_df[
        'mean_miou'
    ].to_numpy()


    auc = np.trapz(
        y,
        x
    )


    # Normalize because evaluated interval is
    # 0.25 -> 1.00 rather than 0 -> 1.
    normalized_auc = (
        auc /
        (
            x.max()
            - x.min()
        )
    )


    curve_rows.append({

        'model':
            model_name,

        'retention_curve_auc':
            float(
                auc
            ),

        'normalized_retention_score':
            float(
                normalized_auc
            )
    })


retention_curve_df = (
    pd.DataFrame(
        curve_rows
    )
    .sort_values(
        'normalized_retention_score',
        ascending=False
    )
    .reset_index(
        drop=True
    )
)


display(
    retention_curve_df
)

