"""## 46. Parameter-efficiency audit

### 46.1 Current model parameter decomposition
"""

# -------------------------------------------------------
# Section 46.1
# Parameter decomposition of matched models
# -------------------------------------------------------

PARAMETER_AUDIT_ROWS = []


FULL_MODEL_SPECS = {

    'CfC': (
        LatentGridCNNCfCSegmentationModel,
        LATENT_CFC_CONFIG
    ),

    'LSTM': (
        LatentGridCNNLSTMSegmentationModel,
        LATENT_RECURRENT_COMMON_CONFIG
    ),

    'GRU': (
        LatentGridCNNGRUSegmentationModel,
        LATENT_RECURRENT_COMMON_CONFIG
    )
}


for model_name, (
    model_class,
    model_config
) in FULL_MODEL_SPECS.items():

    model = model_class(
        **model_config
    )


    total_parameters = sum(
        p.numel()
        for p in model.parameters()
    )


    trainable_parameters = sum(
        p.numel()
        for p in model.parameters()
        if p.requires_grad
    )


    temporal_parameters = sum(
        p.numel()
        for p in model.temporal.parameters()
    )


    temporal_trainable_parameters = sum(
        p.numel()
        for p in model.temporal.parameters()
        if p.requires_grad
    )


    non_temporal_parameters = (
        total_parameters
        -
        temporal_parameters
    )


    parameter_memory_mb = sum(
        p.numel() * p.element_size()
        for p in model.parameters()
    ) / (1024 ** 2)


    PARAMETER_AUDIT_ROWS.append({

        'model':
            model_name,

        'total_parameters':
            total_parameters,

        'trainable_parameters':
            trainable_parameters,

        'temporal_parameters':
            temporal_parameters,

        'temporal_trainable_parameters':
            temporal_trainable_parameters,

        'non_temporal_parameters':
            non_temporal_parameters,

        'temporal_fraction':
            temporal_parameters
            / total_parameters,

        'parameter_memory_mb':
            parameter_memory_mb
    })


    del model


