"""### 47.5 — Save the whole-model efficiency result"""

# -------------------------------------------------------
# Section 47.5
# Whole-model parameter-efficiency summary
# -------------------------------------------------------

full_reference = {
    'CfC': {
        'parameters': 93092,
        'miou': 0.7460007249188529
    },

    'LSTM': {
        'parameters': 95236,
        'miou': 0.741904
    },

    'GRU': {
        'parameters': 93124,
        'miou': 0.735523
    }
}


efficiency_df = (
    capacity_complete_df[
        [
            'capacity',
            'model',
            'total_parameters',
            'temporal_parameters',
            'validation_mean_iou',
            'validation_macro_f1'
        ]
    ]
    .copy()
)


efficiency_df[
    'parameter_reduction_vs_own_full'
] = efficiency_df.apply(
    lambda row:
        1.0
        -
        row['total_parameters']
        /
        full_reference[
            row['model']
        ]['parameters'],
    axis=1
)


efficiency_df[
    'miou_change_vs_own_full'
] = efficiency_df.apply(
    lambda row:
        row['validation_mean_iou']
        -
        full_reference[
            row['model']
        ]['miou'],
    axis=1
)


efficiency_df[
    'miou_retention_vs_own_full'
] = efficiency_df.apply(
    lambda row:
        row['validation_mean_iou']
        /
        full_reference[
            row['model']
        ]['miou'],
    axis=1
)


# -------------------------------------------------------
# Global Pareto frontier
# Higher mIoU and fewer parameters are preferred.
# -------------------------------------------------------

pareto_flags = []


for i, row_i in efficiency_df.iterrows():

    dominated = False

    for j, row_j in efficiency_df.iterrows():

        if i == j:
            continue

        fewer_or_equal = (
            row_j['total_parameters']
            <=
            row_i['total_parameters']
        )

        better_or_equal = (
            row_j['validation_mean_iou']
            >=
            row_i['validation_mean_iou']
        )

        strictly_better = (
            row_j['total_parameters']
            <
            row_i['total_parameters']
            or
            row_j['validation_mean_iou']
            >
            row_i['validation_mean_iou']
        )

        if (
            fewer_or_equal
            and better_or_equal
            and strictly_better
        ):

            dominated = True
            break


    pareto_flags.append(
        not dominated
    )


efficiency_df[
    'pareto_efficient'
] = pareto_flags


efficiency_df = (
    efficiency_df
    .sort_values(
        'total_parameters'
    )
    .reset_index(
        drop=True
    )
)


