"""### 48.5 — Smoke-test all compressed models"""

# -------------------------------------------------------
# Section 48.5
# Compressed temporal-core smoke tests
# -------------------------------------------------------

TEMPORAL_COMPRESSION_REDUCED_HIDDEN = [
    8,
    16,
    24
]

TEMPORAL_COMPRESSION_MODELS = [
    'CfC',
    'LSTM',
    'GRU'
]


compression_smoke_rows = []


sample_batch = next(
    iter(valid_loader)
)


for model_name in TEMPORAL_COMPRESSION_MODELS:

    for hidden_size in (
        TEMPORAL_COMPRESSION_REDUCED_HIDDEN
    ):

        set_reproducible_seed(42)

        model, _ = (
            build_fixed_backbone_temporal_model(
                model_name,
                hidden_size
            )
        )

        model = model.to(DEVICE)
        model.eval()


        batch_device = (
            move_batch_to_device(
                sample_batch,
                DEVICE
            )
        )


        with torch.no_grad():

            logits = forward_model(
                model,
                batch_device
            )


            loss = WEIGHTED_CRITERION(
                logits,
                batch_device['y']
            )


        compression_smoke_rows.append({

            'model':
                model_name,

            'hidden_size':
                hidden_size,

            'output_shape':
                str(
                    tuple(logits.shape)
                ),

            'loss':
                float(loss.item()),

            'finite':
                bool(
                    torch.isfinite(
                        logits
                    ).all().item()
                )
        })


        del model
        del logits

        gc.collect()

        if DEVICE.type == 'cuda':
            torch.cuda.empty_cache()


compression_smoke_df = pd.DataFrame(
    compression_smoke_rows
)


display(
    compression_smoke_df
)


assert compression_smoke_df[
    'finite'
].all()


print(
    'All compressed temporal models passed.'
)

