"""#### 48.6.2 Train the nine reduced configurations"""

import gc

TEMPORAL_COMPRESSION_REDUCED_HIDDEN = [
    8,
    16,
    24
]

TEMPORAL_COMPRESSION_MODELS = [
    'CfC',
    'LSTM',
    'GRU'
]

print('Device:', DEVICE)
print('AMP:', USE_AMP)

print(
    'fit_neural_model:',
    callable(fit_neural_model)
)

print(
    'CfC class:',
    LatentGridCNNCfCSegmentationModel
)

print(
    'LSTM class:',
    LatentGridCNNLSTMSegmentationModel
)

print(
    'GRU class:',
    LatentGridCNNGRUSegmentationModel
)

print(
    'Completed temporal pairs:',
    sorted(completed_temporal_pairs)
)

# -------------------------------------------------------
# Section 48.6.2
# Seed-42 fixed-backbone temporal compression sweep
# -------------------------------------------------------

TEMPORAL_COMPRESSION_SEED = 42


for hidden_size in (
    TEMPORAL_COMPRESSION_REDUCED_HIDDEN
):

    for model_name in (
        TEMPORAL_COMPRESSION_MODELS
    ):

        pair = (
            model_name,
            int(hidden_size)
        )


        if pair in completed_temporal_pairs:

            print(
                'Skipping completed:',
                pair
            )

            continue


        print(
            '\n' + '=' * 72
        )

        print(
            'Temporal-core compression experiment'
        )

        print(
            'Model:',
            model_name
        )

        print(
            'Hidden size:',
            hidden_size
        )

        print(
            'Seed:',
            TEMPORAL_COMPRESSION_SEED
        )

        print(
            '=' * 72
        )


        # -----------------------------------------------
        # Reproducible fresh model
        # -----------------------------------------------

        set_reproducible_seed(
            TEMPORAL_COMPRESSION_SEED
        )


        model, model_config = (
            build_fixed_backbone_temporal_model(
                model_name,
                hidden_size
            )
        )


        model = model.to(
            DEVICE
        )


        total_parameters = sum(
            p.numel()
            for p in model.parameters()
        )


        trainable_parameters = sum(
            p.numel()
            for p in model.parameters()
            if p.requires_grad
        )


        temporal_parameters = sum(
            p.numel()
            for p in (
                model.temporal.parameters()
            )
        )


        non_temporal_parameters = (
            total_parameters
            -
            temporal_parameters
        )


        assert (
            non_temporal_parameters
            ==
            86788
        )


        train_loader_seed42 = (
            make_multiseed_train_loader(
                TEMPORAL_COMPRESSION_SEED
            )
        )


        safe_name = (
            model_name.lower()
        )


        checkpoint_path = (
            TEMPORAL_COMPRESSION_CHECKPOINT_DIR /
            (
                f'{safe_name}_'
                f'h{hidden_size}_'
                f'seed42_best.pt'
            )
        )


        history_path = (
            TEMPORAL_COMPRESSION_SWEEP_DIR /
            (
                f'{safe_name}_'
                f'h{hidden_size}_'
                f'seed42_history.csv'
            )
        )


        print(
            'Total parameters:',
            total_parameters
        )

        print(
            'Temporal subsystem parameters:',
            temporal_parameters
        )

        print(
            'Non-temporal parameters:',
            non_temporal_parameters
        )


        # -----------------------------------------------
        # Training
        # -----------------------------------------------

        training_result = (
            fit_neural_model(

                model_name=(
                    f'fixed_backbone_'
                    f'{safe_name}_'
                    f'h{hidden_size}_'
                    f'seed42'
                ),

                model=model,

                model_config=model_config,

                train_data_loader=(
                    train_loader_seed42
                ),

                validation_data_loader=(
                    valid_loader
                ),

                criterion=(
                    WEIGHTED_CRITERION
                ),

                checkpoint_path=(
                    checkpoint_path
                ),

                history_path=(
                    history_path
                ),

                maximum_epochs=(
                    TRAINING_CONFIG[
                        'maximum_epochs'
                    ]
                )
            )
        )


        validation_metrics = (
            evaluate_model(

                model=(
                    training_result[
                        'model'
                    ]
                ),

                data_loader=(
                    valid_loader
                ),

                criterion=(
                    WEIGHTED_CRITERION
                ),

                device=DEVICE
            )
        )


        result_row = {

            'model':
                model_name,

            'hidden_size':
                int(hidden_size),

            'seed':
                TEMPORAL_COMPRESSION_SEED,

            'total_parameters':
                int(total_parameters),

            'trainable_parameters':
                int(trainable_parameters),

            'temporal_parameters':
                int(temporal_parameters),

            'non_temporal_parameters':
                int(non_temporal_parameters),

            'best_epoch':
                int(
                    training_result[
                        'best_epoch'
                    ]
                ),

            'validation_mean_iou':
                float(
                    validation_metrics[
                        'mean_iou'
                    ]
                ),

            'validation_macro_f1':
                float(
                    validation_metrics[
                        'macro_f1'
                    ]
                ),

            'validation_overall_accuracy':
                float(
                    validation_metrics[
                        'overall_accuracy'
                    ]
                ),

            'validation_kappa':
                float(
                    validation_metrics[
                        'kappa'
                    ]
                ),

            'validation_loss':
                float(
                    validation_metrics[
                        'loss'
                    ]
                ),

            'training_seconds':
                float(
                    training_result[
                        'total_training_seconds'
                    ]
                ),

            'checkpoint_path':
                str(
                    checkpoint_path
                )
        }


        TEMPORAL_COMPRESSION_RESULTS.append(
            result_row
        )


        current_df = (
            pd.DataFrame(
                TEMPORAL_COMPRESSION_RESULTS
            )
            .drop_duplicates(
                subset=[
                    'model',
                    'hidden_size'
                ],
                keep='last'
            )
            .sort_values(
                [
                    'hidden_size',
                    'model'
                ]
            )
            .reset_index(
                drop=True
            )
        )


        current_df.to_csv(
            TEMPORAL_COMPRESSION_RESULTS_PATH,
            index=False
        )


        completed_temporal_pairs.add(
            pair
        )


        print(
            '\nCompleted:'
        )

        display(
            pd.DataFrame(
                [result_row]
            )
        )


        del model
        del training_result
        del train_loader_seed42

        gc.collect()

        if DEVICE.type == 'cuda':
            torch.cuda.empty_cache()

