"""#### 48.9.1 — Key parameter-efficiency comparisons"""

# -------------------------------------------------------
# Section 48.9.1
# Key parameter-efficiency comparisons
# -------------------------------------------------------

def get_temporal_summary_row(
    model_name,
    hidden_size
):

    return (
        temporal_summary_df[
            (
                temporal_summary_df[
                    'model'
                ] == model_name
            )
            &
            (
                temporal_summary_df[
                    'hidden_size'
                ] == hidden_size
            )
        ]
        .iloc[0]
    )


cfc8 = get_temporal_summary_row(
    'CfC',
    8
)

cfc16 = get_temporal_summary_row(
    'CfC',
    16
)

cfc32 = get_temporal_summary_row(
    'CfC',
    32
)

lstm32 = get_temporal_summary_row(
    'LSTM',
    32
)

gru32 = get_temporal_summary_row(
    'GRU',
    32
)

gru24 = get_temporal_summary_row(
    'GRU',
    24
)


comparison_rows = []


for label, reference in [

    (
        'Full CfC h=32',
        cfc32
    ),

    (
        'Full LSTM h=32',
        lstm32
    ),

    (
        'Full GRU h=32',
        gru32
    ),

    (
        'GRU h=24',
        gru24
    )
]:

    comparison_rows.append({

        'comparison':
            f'CfC h=16 vs {label}',

        'cfc16_temporal_parameters':
            int(
                cfc16[
                    'temporal_parameters'
                ]
            ),

        'reference_temporal_parameters':
            int(
                reference[
                    'temporal_parameters'
                ]
            ),

        'parameter_reduction_fraction':
            float(
                1.0
                -
                (
                    cfc16[
                        'temporal_parameters'
                    ]
                    /
                    reference[
                        'temporal_parameters'
                    ]
                )
            ),

        'parameter_reduction_percent':
            float(
                100.0
                *
                (
                    1.0
                    -
                    (
                        cfc16[
                            'temporal_parameters'
                        ]
                        /
                        reference[
                            'temporal_parameters'
                        ]
                    )
                )
            ),

        'cfc16_mean_miou':
            float(
                cfc16[
                    'mean_miou'
                ]
            ),

        'reference_mean_miou':
            float(
                reference[
                    'mean_miou'
                ]
            ),

        'miou_difference':
            float(
                cfc16[
                    'mean_miou'
                ]
                -
                reference[
                    'mean_miou'
                ]
            )
    })


