"""### 50.6 Cross-year temporal-transfer analysis

Compares each frozen model checkpoint on the same Region B patches using
Sentinel-2 observations from 2023 and 2024.

Each model/seed pair is matched directly across years. Positive differences
indicate higher agreement with the fixed ESA WorldCover reference in 2024,
whereas negative differences indicate a reduction under the interannual
Sentinel-2 domain shift.
"""

# -------------------------------------------------------
# Section 50.6
# Direct 2023 -> 2024 comparison
# -------------------------------------------------------

SPATIAL_TEST_2023_PATH = (
    RESULTS_DIR /
    'latent_grid_multiseed_spatial_test_results.csv'
)


assert SPATIAL_TEST_2023_PATH.exists(), (
    f'Missing 2023 Region B results: '
    f'{SPATIAL_TEST_2023_PATH}'
)


# -------------------------------------------------------
# Load original 2023 Region B results
# -------------------------------------------------------

temporal_transfer_2023_df = pd.read_csv(
    SPATIAL_TEST_2023_PATH
)


print(
    '2023 results:',
    temporal_transfer_2023_df.shape
)

print(
    '2024 results:',
    temporal_transfer_2024_df.shape
)


assert len(
    temporal_transfer_2023_df
) == 9

assert len(
    temporal_transfer_2024_df
) == 9


# -------------------------------------------------------
# Rename metrics consistently
# -------------------------------------------------------

metrics_2023 = (
    temporal_transfer_2023_df[
        [
            'model',
            'seed',
            'test_overall_accuracy',
            'test_macro_f1',
            'test_weighted_f1',
            'test_mean_iou',
            'test_kappa'
        ]
    ]
    .rename(
        columns={
            'test_overall_accuracy':
                'accuracy_2023',

            'test_macro_f1':
                'macro_f1_2023',

            'test_weighted_f1':
                'weighted_f1_2023',

            'test_mean_iou':
                'mean_iou_2023',

            'test_kappa':
                'kappa_2023'
        }
    )
)


metrics_2024 = (
    temporal_transfer_2024_df[
        [
            'model',
            'seed',
            'overall_accuracy',
            'macro_f1',
            'weighted_f1',
            'mean_iou',
            'kappa'
        ]
    ]
    .rename(
        columns={
            'overall_accuracy':
                'accuracy_2024',

            'macro_f1':
                'macro_f1_2024',

            'weighted_f1':
                'weighted_f1_2024',

            'mean_iou':
                'mean_iou_2024',

            'kappa':
                'kappa_2024'
        }
    )
)


# -------------------------------------------------------
# Match exactly by architecture and seed
# -------------------------------------------------------

temporal_transfer_comparison_df = (
    metrics_2023
    .merge(
        metrics_2024,
        on=[
            'model',
            'seed'
        ],
        how='inner',
        validate='one_to_one'
    )
    .sort_values(
        [
            'model',
            'seed'
        ]
    )
    .reset_index(
        drop=True
    )
)


assert len(
    temporal_transfer_comparison_df
) == 9


# -------------------------------------------------------
# Calculate 2024 - 2023 changes
# -------------------------------------------------------

for metric in [
    'accuracy',
    'macro_f1',
    'weighted_f1',
    'mean_iou',
    'kappa'
]:

    temporal_transfer_comparison_df[
        f'delta_{metric}'
    ] = (
        temporal_transfer_comparison_df[
            f'{metric}_2024'
        ]
        -
        temporal_transfer_comparison_df[
            f'{metric}_2023'
        ]
    )


# Relative mIoU change (% of 2023 performance).
temporal_transfer_comparison_df[
    'relative_miou_change_pct'
] = (
    temporal_transfer_comparison_df[
        'delta_mean_iou'
    ]
    /
    temporal_transfer_comparison_df[
        'mean_iou_2023'
    ]
    * 100.0
)


# -------------------------------------------------------
# Display the central comparison
# -------------------------------------------------------

display(
    temporal_transfer_comparison_df[
        [
            'model',
            'seed',
            'mean_iou_2023',
            'mean_iou_2024',
            'delta_mean_iou',
            'relative_miou_change_pct',
            'macro_f1_2023',
            'macro_f1_2024',
            'delta_macro_f1',
            'accuracy_2023',
            'accuracy_2024',
            'delta_accuracy',
            'kappa_2023',
            'kappa_2024',
            'delta_kappa'
        ]
    ]
)


# -------------------------------------------------------
# Save seed-level comparison
# -------------------------------------------------------

TEMPORAL_TRANSFER_COMPARISON_PATH = (
    TEMPORAL_TRANSFER_RESULT_DIR /
    '2023_2024_seed_level_comparison.csv'
)


temporal_transfer_comparison_df.to_csv(
    TEMPORAL_TRANSFER_COMPARISON_PATH,
    index=False
)


print(
    'Saved:',
    TEMPORAL_TRANSFER_COMPARISON_PATH
)

"""#### 50.6.1 — Model-level temporal-transfer summary"""

# -------------------------------------------------------
# Section 50.6.1
# Mean cross-year performance by architecture
# -------------------------------------------------------

temporal_transfer_summary_df = (

    temporal_transfer_comparison_df

    .groupby(
        'model'
    )

    .agg(

        mean_miou_2023=(
            'mean_iou_2023',
            'mean'
        ),

        std_miou_2023=(
            'mean_iou_2023',
            'std'
        ),

        mean_miou_2024=(
            'mean_iou_2024',
            'mean'
        ),

        std_miou_2024=(
            'mean_iou_2024',
            'std'
        ),

        mean_delta_miou=(
            'delta_mean_iou',
            'mean'
        ),

        std_delta_miou=(
            'delta_mean_iou',
            'std'
        ),

        mean_relative_miou_change_pct=(
            'relative_miou_change_pct',
            'mean'
        ),

        mean_macro_f1_2023=(
            'macro_f1_2023',
            'mean'
        ),

        mean_macro_f1_2024=(
            'macro_f1_2024',
            'mean'
        ),

        mean_delta_macro_f1=(
            'delta_macro_f1',
            'mean'
        ),

        mean_accuracy_2023=(
            'accuracy_2023',
            'mean'
        ),

        mean_accuracy_2024=(
            'accuracy_2024',
            'mean'
        ),

        mean_delta_accuracy=(
            'delta_accuracy',
            'mean'
        ),

        mean_kappa_2023=(
            'kappa_2023',
            'mean'
        ),

        mean_kappa_2024=(
            'kappa_2024',
            'mean'
        ),

        mean_delta_kappa=(
            'delta_kappa',
            'mean'
        )
    )

    .reset_index()

    .sort_values(
        'mean_miou_2024',
        ascending=False
    )

    .reset_index(
        drop=True
    )
)


temporal_transfer_summary_df.insert(
    0,
    'rank_2024',
    np.arange(
        1,
        len(
            temporal_transfer_summary_df
        ) + 1
    )
)


display(
    temporal_transfer_summary_df
)


TEMPORAL_TRANSFER_SUMMARY_COMPARISON_PATH = (
    TEMPORAL_TRANSFER_RESULT_DIR /
    '2023_2024_model_summary.csv'
)


temporal_transfer_summary_df.to_csv(
    TEMPORAL_TRANSFER_SUMMARY_COMPARISON_PATH,
    index=False
)


print(
    'Saved:',
    TEMPORAL_TRANSFER_SUMMARY_COMPARISON_PATH
)

"""#### 50.6.2 — Pairwise ranking in 2024"""

# -------------------------------------------------------
# Section 50.6.2
# Pairwise 2024 model differences
# -------------------------------------------------------

mean_2024_by_model = (
    temporal_transfer_summary_df
    .set_index('model')[
        'mean_miou_2024'
    ]
)


cfc_vs_lstm_2024 = (
    mean_2024_by_model['CfC']
    -
    mean_2024_by_model['LSTM']
)

cfc_vs_gru_2024 = (
    mean_2024_by_model['CfC']
    -
    mean_2024_by_model['GRU']
)

lstm_vs_gru_2024 = (
    mean_2024_by_model['LSTM']
    -
    mean_2024_by_model['GRU']
)


print(
    '2024 CfC - LSTM mIoU:',
    f'{cfc_vs_lstm_2024:+.6f}'
)

print(
    '2024 CfC - GRU mIoU:',
    f'{cfc_vs_gru_2024:+.6f}'
)

print(
    '2024 LSTM - GRU mIoU:',
    f'{lstm_vs_gru_2024:+.6f}'
)


# Seed-wise wins
for competitor in [
    'LSTM',
    'GRU'
]:

    wins = 0

    for seed in [
        42,
        123,
        2026
    ]:

        cfc_value = (
            temporal_transfer_comparison_df.loc[
                (
                    temporal_transfer_comparison_df[
                        'model'
                    ] == 'CfC'
                )
                &
                (
                    temporal_transfer_comparison_df[
                        'seed'
                    ] == seed
                ),
                'mean_iou_2024'
            ].iloc[0]
        )

        competitor_value = (
            temporal_transfer_comparison_df.loc[
                (
                    temporal_transfer_comparison_df[
                        'model'
                    ] == competitor
                )
                &
                (
                    temporal_transfer_comparison_df[
                        'seed'
                    ] == seed
                ),
                'mean_iou_2024'
            ].iloc[0]
        )

        if cfc_value > competitor_value:
            wins += 1


    print(
        f'CfC beats {competitor} in 2024:',
        f'{wins}/3 seeds'
    )

"""### 50.7 Per-class cross-year temporal-transfer analysis

Compares class-specific performance for each frozen model and seed between
the 2023 and 2024 Region B evaluations.

Because both years use the same 30 patches and the same fixed ESA WorldCover
reference maps, the support of each class must be identical across years.
Changes therefore reflect differences in model predictions under the 2024
Sentinel-2 temporal domain rather than changes in the evaluation target.
"""

# -------------------------------------------------------
# Section 50.7
# Seed-level per-class 2023 -> 2024 comparison
# -------------------------------------------------------

PER_CLASS_2023_PATH = (
    RESULTS_DIR /
    'latent_grid_multiseed_spatial_test_per_class.csv'
)


assert PER_CLASS_2023_PATH.exists(), (
    f'Missing 2023 per-class results: '
    f'{PER_CLASS_2023_PATH}'
)


# -------------------------------------------------------
# Load 2023 and 2024 per-class results
# -------------------------------------------------------

per_class_2023_df = pd.read_csv(
    PER_CLASS_2023_PATH
)

per_class_2024_df = (
    temporal_transfer_2024_class_df
    .copy()
)


print(
    '2023 per-class rows:',
    len(per_class_2023_df)
)

print(
    '2024 per-class rows:',
    len(per_class_2024_df)
)


print(
    '\n2023 columns:',
    per_class_2023_df.columns.tolist()
)

print(
    '\n2024 columns:',
    per_class_2024_df.columns.tolist()
)


assert len(
    per_class_2023_df
) == 9 * N_CLASSES

assert len(
    per_class_2024_df
) == 9 * N_CLASSES


# -------------------------------------------------------
# Retain and rename comparable metrics
# -------------------------------------------------------

per_class_2023 = (
    per_class_2023_df[
        [
            'model',
            'seed',
            'class_id',
            'class_name',
            'support',
            'precision',
            'recall',
            'f1',
            'iou'
        ]
    ]
    .rename(
        columns={
            'support':
                'support_2023',

            'precision':
                'precision_2023',

            'recall':
                'recall_2023',

            'f1':
                'f1_2023',

            'iou':
                'iou_2023'
        }
    )
)


per_class_2024 = (
    per_class_2024_df[
        [
            'model',
            'seed',
            'class_id',
            'class_name',
            'support',
            'precision',
            'recall',
            'f1',
            'iou'
        ]
    ]
    .rename(
        columns={
            'support':
                'support_2024',

            'precision':
                'precision_2024',

            'recall':
                'recall_2024',

            'f1':
                'f1_2024',

            'iou':
                'iou_2024'
        }
    )
)


# -------------------------------------------------------
# Exact model + seed + class pairing
# -------------------------------------------------------

temporal_transfer_per_class_df = (
    per_class_2023
    .merge(
        per_class_2024,

        on=[
            'model',
            'seed',
            'class_id',
            'class_name'
        ],

        how='inner',

        validate='one_to_one'
    )
    .sort_values(
        [
            'model',
            'seed',
            'class_id'
        ]
    )
    .reset_index(
        drop=True
    )
)


assert len(
    temporal_transfer_per_class_df
) == 36


# -------------------------------------------------------
# Same static reference -> class support must be exact
# -------------------------------------------------------

assert np.array_equal(

    temporal_transfer_per_class_df[
        'support_2023'
    ].to_numpy(),

    temporal_transfer_per_class_df[
        'support_2024'
    ].to_numpy()
)


# -------------------------------------------------------
# Calculate 2024 - 2023 differences
# -------------------------------------------------------

for metric in [
    'precision',
    'recall',
    'f1',
    'iou'
]:

    temporal_transfer_per_class_df[
        f'delta_{metric}'
    ] = (
        temporal_transfer_per_class_df[
            f'{metric}_2024'
        ]
        -
        temporal_transfer_per_class_df[
            f'{metric}_2023'
        ]
    )


temporal_transfer_per_class_df[
    'relative_iou_change_pct'
] = np.where(

    temporal_transfer_per_class_df[
        'iou_2023'
    ] != 0,

    (
        temporal_transfer_per_class_df[
            'delta_iou'
        ]
        /
        temporal_transfer_per_class_df[
            'iou_2023'
        ]
        * 100.0
    ),

    np.nan
)


# -------------------------------------------------------
# Display seed-level class comparison
# -------------------------------------------------------

display(
    temporal_transfer_per_class_df[
        [
            'model',
            'seed',
            'class_name',
            'support_2023',
            'iou_2023',
            'iou_2024',
            'delta_iou',
            'relative_iou_change_pct',
            'f1_2023',
            'f1_2024',
            'delta_f1',
            'precision_2023',
            'precision_2024',
            'delta_precision',
            'recall_2023',
            'recall_2024',
            'delta_recall'
        ]
    ]
)


# -------------------------------------------------------
# Save
# -------------------------------------------------------

PER_CLASS_TRANSFER_PATH = (
    TEMPORAL_TRANSFER_RESULT_DIR /
    '2023_2024_per_class_seed_level.csv'
)


temporal_transfer_per_class_df.to_csv(
    PER_CLASS_TRANSFER_PATH,
    index=False
)


print(
    '\nClass support across years: EXACT'
)

print(
    'Per-class model/seed pairs:',
    len(
        temporal_transfer_per_class_df
    )
)

print(
    'Saved:',
    PER_CLASS_TRANSFER_PATH
)

