for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    model_rows = (
        per_class_transfer_summary_df[
            per_class_transfer_summary_df[
                'model'
            ] == model_name
        ]
    )

    worst_row = (
        model_rows
        .sort_values(
            'mean_delta_iou'
        )
        .iloc[0]
    )


    print(
        f'{model_name}: '
        f'{worst_row["class_name"]} | '
        f'{worst_row["mean_delta_iou"]:+.6f}'
    )

"""### 50.8 Cross-year confusion-shift analysis

Examines how pixel-level classification errors change between the 2023 and 2024
Region B evaluations.

For each architecture, confusion matrices are averaged across the three frozen
seeds and normalized by reference class. The difference between the normalized
2024 and 2023 matrices reveals which class-to-class confusions increased under
the cross-year Sentinel-2 domain shift.
"""

# -------------------------------------------------------
# Section 50.8
# Cross-year confusion-matrix shift
# -------------------------------------------------------

CONFUSION_YEARS = {
    2023: test_loader,
    2024: test_2024_loader
}

confusion_records = []


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    spec = (
        TEMPORAL_TRANSFER_MODEL_SPECS[
            model_name
        ]
    )


    for seed in [
        42,
        123,
        2026
    ]:

        checkpoint_path = (
            TEMPORAL_TRANSFER_CHECKPOINTS[
                model_name
            ][
                seed
            ]
        )


        print(
            '\n' + '=' * 72
        )

        print(
            model_name,
            '| seed',
            seed
        )

        print(
            '=' * 72
        )


        # -----------------------------------------------
        # Load frozen model once
        # -----------------------------------------------

        model = (
            spec[
                'class'
            ](
                **spec[
                    'config'
                ]
            )
            .to(
                DEVICE
            )
        )


        checkpoint = torch.load(
            checkpoint_path,
            map_location=DEVICE,
            weights_only=False
        )


        model.load_state_dict(
            checkpoint[
                'model_state_dict'
            ],
            strict=True
        )


        # -----------------------------------------------
        # Evaluate both years
        # -----------------------------------------------

        for year, loader in (
            CONFUSION_YEARS.items()
        ):

            metrics = evaluate_model(
                model=model,
                data_loader=loader,
                criterion=(
                    WEIGHTED_CRITERION
                ),
                device=DEVICE
            )


            confusion = (
                metrics[
                    'confusion_matrix'
                ]
                .astype(
                    np.int64
                )
            )


            assert confusion.shape == (
                N_CLASSES,
                N_CLASSES
            )


            confusion_records.append({
                'model':
                    model_name,

                'seed':
                    int(seed),

                'year':
                    int(year),

                'confusion_matrix':
                    confusion
            })


            print(
                year,
                '| mIoU:',
                f'{metrics["mean_iou"]:.6f}'
            )


        del model
        del checkpoint

        gc.collect()

        if DEVICE.type == 'cuda':
            torch.cuda.empty_cache()


print(
    '\nConfusion evaluations:',
    len(
        confusion_records
    )
)

assert len(
    confusion_records
) == 18

"""#### 50.8.1 — Average normalized confusion matrices"""

# -------------------------------------------------------
# Section 50.8.1
# Mean normalized confusion matrices across seeds
# -------------------------------------------------------

mean_confusions = {}
normalized_confusions = {}


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    mean_confusions[
        model_name
    ] = {}

    normalized_confusions[
        model_name
    ] = {}


    for year in [
        2023,
        2024
    ]:

        matrices = [
            record[
                'confusion_matrix'
            ]
            for record
            in confusion_records
            if (
                record[
                    'model'
                ] == model_name
                and
                record[
                    'year'
                ] == year
            )
        ]


        assert len(
            matrices
        ) == 3


        mean_matrix = (
            np.mean(
                np.stack(
                    matrices,
                    axis=0
                ),
                axis=0
            )
        )


        row_totals = (
            mean_matrix
            .sum(
                axis=1,
                keepdims=True
            )
        )


        normalized_matrix = np.divide(
            mean_matrix,
            row_totals,
            out=np.zeros_like(
                mean_matrix,
                dtype=np.float64
            ),
            where=(
                row_totals != 0
            )
        )


        mean_confusions[
            model_name
        ][
            year
        ] = mean_matrix


        normalized_confusions[
            model_name
        ][
            year
        ] = normalized_matrix


print(
    'Mean three-seed confusion matrices ready.'
)

"""#### 50.8.2 — Find the strongest confusion changes"""

# -------------------------------------------------------
# Section 50.8.2
# Identify cross-year confusion changes
# -------------------------------------------------------

confusion_shift_rows = []


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    matrix_2023 = (
        normalized_confusions[
            model_name
        ][
            2023
        ]
    )

    matrix_2024 = (
        normalized_confusions[
            model_name
        ][
            2024
        ]
    )


    delta_matrix = (
        matrix_2024
        - matrix_2023
    )


    for reference_class in range(
        N_CLASSES
    ):

        for predicted_class in range(
            N_CLASSES
        ):

            confusion_shift_rows.append({

                'model':
                    model_name,

                'reference_class_id':
                    reference_class,

                'reference_class':
                    CLASS_NAMES[
                        reference_class
                    ],

                'predicted_class_id':
                    predicted_class,

                'predicted_class':
                    CLASS_NAMES[
                        predicted_class
                    ],

                'rate_2023':
                    float(
                        matrix_2023[
                            reference_class,
                            predicted_class
                        ]
                    ),

                'rate_2024':
                    float(
                        matrix_2024[
                            reference_class,
                            predicted_class
                        ]
                    ),

                'delta_rate':
                    float(
                        delta_matrix[
                            reference_class,
                            predicted_class
                        ]
                    )
            })


confusion_shift_df = pd.DataFrame(
    confusion_shift_rows
)


# -------------------------------------------------------
# Off-diagonal changes only
# -------------------------------------------------------

error_shift_df = (
    confusion_shift_df[
        confusion_shift_df[
            'reference_class_id'
        ]
        !=
        confusion_shift_df[
            'predicted_class_id'
        ]
    ]
    .copy()
)


print(
    'Largest increases in confusion '
    '(2024 - 2023):'
)


display(
    error_shift_df
    .sort_values(
        'delta_rate',
        ascending=False
    )
    .head(15)
)


print(
    '\nLargest reductions in confusion:'
)


display(
    error_shift_df
    .sort_values(
        'delta_rate',
        ascending=True
    )
    .head(15)
)

"""#### 50.8.3 — Specifically investigate false Built-up predictions"""

# -------------------------------------------------------
# Section 50.8.3
# Increase in predictions of Built-up
# -------------------------------------------------------

built_up_id = (
    CLASS_NAMES.index(
        'Built-up'
    )
)


built_up_false_positive_shift = (
    error_shift_df[
        error_shift_df[
            'predicted_class_id'
        ] == built_up_id
    ]
    .sort_values(
        [
            'model',
            'delta_rate'
        ],
        ascending=[
            True,
            False
        ]
    )
)


display(
    built_up_false_positive_shift[
        [
            'model',
            'reference_class',
            'rate_2023',
            'rate_2024',
            'delta_rate'
        ]
    ]
)


CONFUSION_SHIFT_PATH = (
    TEMPORAL_TRANSFER_RESULT_DIR /
    '2023_2024_confusion_shift.csv'
)


confusion_shift_df.to_csv(
    CONFUSION_SHIFT_PATH,
    index=False
)


print(
    'Saved:',
    CONFUSION_SHIFT_PATH
)

"""#### 50.8.4 — Quantify the Built-up error shift"""

# -------------------------------------------------------
# Section 50.8.4
# Quantify the Built-up cross-year error shift
# -------------------------------------------------------

built_up_shift_rows = []


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    # ---------------------------------------------------
    # Additional false Built-up predictions originating
    # from the three non-built reference classes
    # ---------------------------------------------------

    false_positive_rows = (
        built_up_false_positive_shift[
            built_up_false_positive_shift[
                'model'
            ] == model_name
        ]
    )


    added_false_built_pixels = 0.0


    for _, row in (
        false_positive_rows.iterrows()
    ):

        reference_class = (
            row[
                'reference_class'
            ]
        )


        class_support = (
            per_class_transfer_summary_df.loc[
                (
                    per_class_transfer_summary_df[
                        'model'
                    ] == model_name
                )
                &
                (
                    per_class_transfer_summary_df[
                        'class_name'
                    ] == reference_class
                ),
                'support'
            ]
            .iloc[0]
        )


        added_false_built_pixels += (
            float(
                class_support
            )
            *
            float(
                row[
                    'delta_rate'
                ]
            )
        )


    # ---------------------------------------------------
    # Additional correctly identified Built-up pixels
    # caused by the increase in Built-up recall
    # ---------------------------------------------------

    built_row = (
        per_class_transfer_summary_df[
            (
                per_class_transfer_summary_df[
                    'model'
                ] == model_name
            )
            &
            (
                per_class_transfer_summary_df[
                    'class_name'
                ] == 'Built-up'
            )
        ]
        .iloc[0]
    )


    built_support = float(
        built_row[
            'support'
        ]
    )


    recovered_true_built_pixels = (
        built_support
        *
        float(
            built_row[
                'mean_delta_recall'
            ]
        )
    )


    net_built_prediction_increase = (
        added_false_built_pixels
        +
        recovered_true_built_pixels
    )


    built_up_shift_rows.append({

        'model':
            model_name,

        'additional_false_built_pixels':
            added_false_built_pixels,

        'additional_correct_built_pixels':
            recovered_true_built_pixels,

        'net_additional_built_predictions':
            net_built_prediction_increase,

        'built_precision_change':
            float(
                built_row[
                    'mean_delta_precision'
                ]
            ),

        'built_recall_change':
            float(
                built_row[
                    'mean_delta_recall'
                ]
            ),

        'built_iou_change':
            float(
                built_row[
                    'mean_delta_iou'
                ]
            )
    })


built_up_shift_summary_df = (
    pd.DataFrame(
        built_up_shift_rows
    )
)


display(
    built_up_shift_summary_df
)


BUILT_UP_SHIFT_PATH = (
    TEMPORAL_TRANSFER_RESULT_DIR /
    '2023_2024_built_up_error_shift.csv'
)


built_up_shift_summary_df.to_csv(
    BUILT_UP_SHIFT_PATH,
    index=False
)


print(
    'Saved:',
    BUILT_UP_SHIFT_PATH
)

"""### 50.9 Final temporal-transfer experiment summary

Consolidates the principal results of the 2023-to-2024 temporal-transfer
experiment. All values are derived from frozen models trained and selected
using only 2023 data and evaluated over the same 30 Region B patches using
Sentinel-2 observations from 2024.

The experiment measures cross-year agreement with the fixed ESA WorldCover
2021 reference and is not interpreted as land-cover change detection.
"""

# -------------------------------------------------------
# Section 50.9
# Consolidated 2023 -> 2024 temporal-transfer results
# -------------------------------------------------------

final_temporal_rows = []


for model_name in [
    'CfC',
    'LSTM',
    'GRU'
]:

    # ---------------------------------------------------
    # Global cross-year metrics
    # ---------------------------------------------------

    global_row = (
        temporal_transfer_summary_df[
            temporal_transfer_summary_df[
                'model'
            ] == model_name
        ]
        .iloc[0]
    )


    # ---------------------------------------------------
    # Built-up class result
    # ---------------------------------------------------

    built_class_row = (
        per_class_transfer_summary_df[
            (
                per_class_transfer_summary_df[
                    'model'
                ] == model_name
            )
            &
            (
                per_class_transfer_summary_df[
                    'class_name'
                ] == 'Built-up'
            )
        ]
        .iloc[0]
    )


    # ---------------------------------------------------
    # Built-up error mechanism
    # ---------------------------------------------------

    built_shift_row = (
        built_up_shift_summary_df[
            built_up_shift_summary_df[
                'model'
            ] == model_name
        ]
        .iloc[0]
    )


    final_temporal_rows.append({

        'model':
            model_name,

        # 2023
        'mean_miou_2023':
            float(
                global_row[
                    'mean_miou_2023'
                ]
            ),

        'std_miou_2023':
            float(
                global_row[
                    'std_miou_2023'
                ]
            ),

        # 2024
        'mean_miou_2024':
            float(
                global_row[
                    'mean_miou_2024'
                ]
            ),

        'std_miou_2024':
            float(
                global_row[
                    'std_miou_2024'
                ]
            ),

        # Temporal change
        'delta_miou':
            float(
                global_row[
                    'mean_delta_miou'
                ]
            ),

        'relative_miou_change_pct':
            float(
                global_row[
                    'mean_relative_miou_change_pct'
                ]
            ),

        # Other 2024 global metrics
        'macro_f1_2024':
            float(
                global_row[
                    'mean_macro_f1_2024'
                ]
            ),

        'overall_accuracy_2024':
            float(
                global_row[
                    'mean_accuracy_2024'
                ]
            ),

        'kappa_2024':
            float(
                global_row[
                    'mean_kappa_2024'
                ]
            ),

        # Built-up
        'built_iou_2023':
            float(
                built_class_row[
                    'mean_iou_2023'
                ]
            ),

        'built_iou_2024':
            float(
                built_class_row[
                    'mean_iou_2024'
                ]
            ),

        'built_delta_iou':
            float(
                built_class_row[
                    'mean_delta_iou'
                ]
            ),

        'built_precision_change':
            float(
                built_shift_row[
                    'built_precision_change'
                ]
            ),

        'built_recall_change':
            float(
                built_shift_row[
                    'built_recall_change'
                ]
            ),

        'additional_false_built_pixels':
            float(
                built_shift_row[
                    'additional_false_built_pixels'
                ]
            ),

        'additional_correct_built_pixels':
            float(
                built_shift_row[
                    'additional_correct_built_pixels'
                ]
            )
    })


final_temporal_summary_df = (
    pd.DataFrame(
        final_temporal_rows
    )
    .sort_values(
        'mean_miou_2024',
        ascending=False
    )
    .reset_index(
        drop=True
    )
)


final_temporal_summary_df.insert(
    0,
    'rank_2024',
    np.arange(
        1,
        len(
            final_temporal_summary_df
        ) + 1
    )
)


display(
    final_temporal_summary_df
)


# -------------------------------------------------------
