# Final inventory of saved experimental outputs
# -------------------------------------------------------

from pathlib import Path
import pandas as pd


experiment_files = []


for path in sorted(
    EXPERIMENT_DIR.rglob('*')
):

    if not path.is_file():
        continue

    suffix = path.suffix.lower()

    if suffix not in {
        '.csv',
        '.json',
        '.npz',
        '.pt',
        '.png',
        '.pdf'
    }:
        continue


    experiment_files.append({

        'relative_path':
            str(
                path.relative_to(
                    EXPERIMENT_DIR
                )
            ),

        'type':
            suffix,

        'size_MB':
            path.stat().st_size
            / 1024**2
    })


